        let center = Vec2::new(40.0 * 16.0, 60.0 * 16.0);
        let slot = pool
            .spawn_hook(crate::projectile::HOOK, center, center + Vec2::new(0.0, 100.0), 11.5, 0, 7.0, 0, 1)
            .expect("the hook row spawns");
