#[cfg(test)]
mod s1_d_4b_8_tests {
    //! S1-D-4b-8 — the aiStyle-2 thrown family completed
    //! (`Projectile.cs:23205-23689`): the per-type state machines the first
    //! landing left out (the 909 frame roll, the 968 head, the 861 pickup +
    //! frame machine, the 304 spawn latch, the 166 town-NPC refusal) and the
    //! exact per-arm `ai[0]` increment semantics. The dust/gore/sound blocks
    //! are documented skips; their `Main.rand` rolls go with them (ANALYSIS).

    use super::*;

    /// A counting stream over the golden `FastRandom` — the RNG proof reads
    /// how many draws each arm consumes, in the C#'s order.
    struct CountingRng {
        inner: tr_core::tile_light::FastRandom,
        ranges: usize,
        floats: usize,
    }
    impl CountingRng {
        fn new() -> Self {
            Self { inner: tr_core::tile_light::FastRandom::new(7), ranges: 0, floats: 0 }
        }
    }
    impl tr_core::loot::DropRng for CountingRng {
        fn next_range(&mut self, min: i32, max: i32) -> i32 {
            self.ranges += 1;
            self.inner.next_range(min, max)
        }
        fn next_float(&mut self) -> f32 {
            self.floats += 1;
            self.inner.next_float()
        }
    }

    fn world() -> World {
        World::new("t".into(), 64, 64)
    }

    /// [`world`] with a dirt floor from row 30 — the town-NPC spawn scan
    /// needs ground under its feet.
    fn ground_world() -> World {
        let mut w = world();
        for x in 0..64 {
            for y in 30..64 {
                let i = w.index(x, y);
                w.tiles[i] = tr_core::tile::Tile { kind: 1, ..Default::default() };
                w.tiles[i].flags |= tr_core::tile::FLAG_ACTIVE;
            }
        }
        w.spawn_x = 20;
        w.spawn_y = 20;
        w.compute_column_surface();
        w.compute_chunks();
        w
    }

    fn just(kind: u16) -> Projectile {
        Projectile {
            active: true,
            kind,
            w: 10.0,
            h: 10.0,
            direction: 1,
            time_left: 18000,
            ..Default::default()
        }
    }

    /// One arm tick with no player and no NPCs — the plain-flight shape.
    fn tick(p: &mut Projectile, w: &World, rng: &mut CountingRng) {
        p.ai_style2(w, &[], None, rng, 0.0);
    }

    /// The dispatch test: every aiStyle-2 row the pool carries reaches the
    /// arm through `match data.ai_style` — one tick moves the age counter
    /// (or the shell's alpha gate) exactly as the C# arm does.
    #[test]
    fn s1_d_4b_8_the_style2_rows_dispatch_to_the_arm() {
        let mut w = world();
        for kind in [SHURIKEN, THROWING_KNIFE, SNOWBALL, SPARK, DUTCHMAN_SHELL] {
            assert_eq!(proj_data(kind).unwrap().ai_style, 2, "kind {kind}");
            let mut pool = ProjectilePool::new();
            let slot = pool
                .spawn_with_data_owned(kind, 0, 100.0, 100.0, 4.0, 0.0, 10, 0.0, 0.0, 0.0)
                .expect("the row");
            let mut rng = CountingRng::new();
            let mut npcs: Vec<Npc> = Vec::new();
            pool.update(
                &mut w,
                &mut npcs,
                None,
                None,
                None,
                YoyoInputs::default(),
                FlailInputs::default(),
                &mut rng,
                0,
                false,
            );
            let p = &pool.slots[slot];
            assert_eq!(p.ai[0], 1.0, "kind {kind}: the arm counted the age");
            assert_eq!(rng.ranges, 0, "kind {kind}: no roll on tick 1");
            assert_eq!(rng.floats, 0, "kind {kind}: no float on tick 1");
        }
    }

    /// `:23257-23275` — the 909: the frame roll latches once
    /// (`1 + Next(6)`), `frame = ai[1] - 1` pins every tick, and the
    /// 38-tick gravity delay holds. RNG: exactly one draw, on tick 1.
    #[test]
    fn s1_d_4b_8_the_909_rolls_its_frame_once() {
        let w = world();
        let mut p = just(909);
        let mut rng = CountingRng::new();
        tick(&mut p, &w, &mut rng);
        assert_eq!(rng.ranges, 1, "the one frame roll");
        assert!((1.0..=6.0).contains(&p.ai[1]), "ai[1] = {}", p.ai[1]);
        assert_eq!(p.frame, p.ai[1] as i32 - 1, "the pinned row");
        let latched = p.ai[1];
        for _ in 0..36 {
            tick(&mut p, &w, &mut rng);
        }
        assert_eq!(rng.ranges, 1, "no re-roll");
        assert_eq!(p.ai[1], latched);
        assert_eq!(p.ai[0], 37.0);
        assert_eq!(p.vel.y, 0.0, "no gravity before tick 38");
        tick(&mut p, &w, &mut rng);
        assert!((p.vel.y - 0.4).abs() < 1e-6, "the +0.4 tick");
        assert!((p.vel.x - 0.0).abs() < 1e-6);
    }

    /// `:23219-23239` + the default tail — the 968: the one-shot latch, the
    /// 50/tick alpha fade floored at 0, `frame = (int)ai[1]`, and the tail's
    /// 20-tick gravity (the 968 has no chain arm). The 8-dust burst's 16
    /// `NextFloat` rolls are skipped with the dust.
    #[test]
    fn s1_d_4b_8_the_968_fades_and_pins_its_frame() {
        let w = world();
        let mut p = just(968);
        p.alpha = 255;
        p.ai[1] = 7.0;
        let mut rng = CountingRng::new();
        tick(&mut p, &w, &mut rng);
        assert_eq!(p.local_ai[0], 1.0, "the latch");
        assert_eq!(p.alpha, 205, "255 - 50");
        assert_eq!(p.frame, 7, "the ai[1] pin");
        assert_eq!(p.ai[0], 1.0, "the tail counts the age");
        assert_eq!(rng.floats, 0, "the dust rolls are skipped");
        for _ in 0..4 {
            tick(&mut p, &w, &mut rng);
        }
        assert_eq!(p.alpha, 5, "205 - 4*50");
        tick(&mut p, &w, &mut rng);
        assert_eq!(p.alpha, 0, "floored at 0");
        assert_eq!(p.local_ai[0], 1.0, "the latch holds");
        assert_eq!(proj_frames(968), 24, "Main.cs:8706");
    }

    /// `:23429-23494` — the 861 glow-stick: the 0.995 air friction, the
    /// +0.1 fall, the 5-tick frame machine wrapping at `projFrames` back to
    /// 1, and the velocity aim (+π/4, the left-facing +π/2 flip).
    #[test]
    fn s1_d_4b_8_the_861_animates_and_aims() {
        let w = world();
        let mut p = just(861);
        p.vel = Vec2::new(4.0, 2.0);
        let mut rng = CountingRng::new();
        tick(&mut p, &w, &mut rng);
        assert_eq!(p.ai[0], 0.0, "the arm owns no ai[0] counter");
        assert!((p.vel.x - 4.0 * 0.995).abs() < 1e-6, "the air friction");
        assert!((p.vel.y - 2.1).abs() < 1e-6, "the fall");
        assert_eq!(p.frame, 1, "frame 0 lifts to 1");
        assert_eq!(p.sprite_direction, 1);
        let expect_rot = p.vel.y.atan2(p.vel.x) + std::f32::consts::FRAC_PI_4;
        assert!((p.rot - expect_rot).abs() < 1e-5, "rot = {}", p.rot);
        // Five ticks per frame: the wrap lands on tick 10 (frame 2 -> 3),
        // and frame 4 wraps back to 1 at projFrames = 4 (Main.cs:8664).
        for _ in 0..14 {
            tick(&mut p, &w, &mut rng);
        }
        assert_eq!(proj_frames(861), 4);
        assert!((1..=3).contains(&p.frame), "frame = {}", p.frame);
        // The left-facing flip.
        p.vel = Vec2::new(-4.0, 0.0);
        tick(&mut p, &w, &mut rng);
        assert_eq!(p.sprite_direction, -1);
        let expect_rot = p.vel.y.atan2(p.vel.x)
            + std::f32::consts::FRAC_PI_4
            + std::f32::consts::FRAC_PI_2;
        assert!((p.rot - expect_rot).abs() < 1e-5);
        // The spent stick (`ai[1] == 1`) resets to frame 0 and keeps the
        // shared spin instead of the aim.
        p.ai[1] = 1.0;
        p.frame = 3;
        p.frame_counter = 4;
        let rot_before = p.rot;
        tick(&mut p, &w, &mut rng);
        assert_eq!(p.frame, 0);
        assert_eq!(p.frame_counter, 0);
        assert!(p.rot > rot_before, "the spin keeps accumulating");
    }

    /// `:23449-23464` — the 861 at rest: the 0.95 ground friction, the 0.5
    /// dead zone and the `Kill()` when both axes are zero.
    #[test]
    fn s1_d_4b_8_the_861_dies_at_rest() {
        let w = world();
        let mut p = just(861);
        p.vel = Vec2::new(0.4, 0.0);
        let mut rng = CountingRng::new();
        tick(&mut p, &w, &mut rng);
        assert_eq!(p.vel.x, 0.0, "0.4 * 0.95 < 0.5 -> the dead zone");
        assert!(!p.active, "the rest kill");
        assert!((p.vel.y - 0.1).abs() < 1e-6, "the fall still runs after Kill");
    }

    /// `:23431-23448` — the 861 pickup: the 30-tick grace, then the owner's
    /// hitbox overlap kills the stick (the single-player fold of the
    /// 255-slot scan).
    #[test]
    fn s1_d_4b_8_the_861_is_picked_up_after_thirty_ticks() {
        let w = world();
        let mut player = crate::player::Player::spawn(&w);
        player.x = 100.0;
        player.y = 100.0;
        let mut p = just(861);
        p.pos = Vec2::new(100.0, 100.0);
        p.vel = Vec2::new(2.0, 0.0);
        let mut rng = CountingRng::new();
        for _ in 0..29 {
            p.ai_style2(&w, &[], Some(&player), &mut rng, 0.0);
            // Keep the stick on the player while it decelerates.
            p.pos = Vec2::new(100.0, 100.0);
            p.vel = Vec2::new(2.0, 0.0);
        }
        assert!(p.active, "the grace period holds");
        assert_eq!(p.local_ai[0], 29.0);
        p.ai_style2(&w, &[], Some(&player), &mut rng, 0.0);
        assert!(!p.active, "tick 30 picks the stick up");
        assert_eq!(p.local_ai[0], 30.0, "the cap");
    }

    /// `:23240-23244` + `:23632-23649` — the 304: the spawn latch (alpha 0),
    /// the aim while rising, then the 30-tick decay (+10 alpha, ×0.9 damage
    /// and knockback) and the `alpha >= 255` kill.
    #[test]
    fn s1_d_4b_8_the_304_latches_fades_and_decays() {
        let w = world();
        let mut p = just(304);
        p.alpha = 255;
        p.damage = 100;
        p.knock_back = 10.0;
        p.vel = Vec2::new(3.0, -4.0);
        let mut rng = CountingRng::new();
        tick(&mut p, &w, &mut rng);
        assert_eq!(p.local_ai[0], 1.0, "the spawn latch");
        assert_eq!(p.alpha, 0, "the invisible start");
        let expect_rot = (-4.0f32).atan2(3.0) + 1.57;
        assert!((p.rot - expect_rot).abs() < 1e-5, "the aim while rising");
        for _ in 0..28 {
            tick(&mut p, &w, &mut rng);
        }
        assert_eq!(p.ai[0], 29.0);
        assert_eq!(p.damage, 100, "no decay before tick 30");
        tick(&mut p, &w, &mut rng);
        assert_eq!(p.alpha, 10);
        assert_eq!(p.damage, 90, "(int)(100 * 0.9)");
        assert!((p.knock_back - 9.0).abs() < 1e-5);
        // 25 more decay ticks: alpha 10 + 25*10 = 260 >= 255 kills it.
        for _ in 0..25 {
            tick(&mut p, &w, &mut rng);
        }
        assert!(!p.active, "the alpha-out kill");
    }

    /// `:23566-23596` — the 166 snowball: the `ai[1] == 1` Rotten Egg mode
    /// kills it on a town-NPC overlap (the C# `return` leaves AI() only —
    /// the movement step still runs); without the overlap the 20-tick
    /// gravity delay holds.
    #[test]
    fn s1_d_4b_8_the_snowball_refuses_the_town_npc() {
        let w = ground_world();
        let mut guide = Npc::spawn_guide(&w, 30).expect("the Guide spawns");
        guide.x = 100.0;
        guide.y = 100.0;
        let npcs = [guide];
        let mut p = just(SNOWBALL);
        p.pos = Vec2::new(104.0, 104.0);
        p.ai[1] = 1.0;
        let mut rng = CountingRng::new();
        p.ai_style2(&w, &npcs, None, &mut rng, 0.0);
        assert!(!p.active, "the town-NPC overlap kills the egg");
        assert_eq!(p.ai[0], 0.0, "the return precedes the age counter");
        // The plain snowball (`ai[1] == 0`) passes the same NPC.
        let mut p2 = just(SNOWBALL);
        p2.pos = Vec2::new(104.0, 104.0);
        p2.vel = Vec2::new(4.0, 0.0);
        p2.ai_style2(&w, &npcs, None, &mut rng, 0.0);
        assert!(p2.active);
        assert_eq!(p2.ai[0], 1.0);
        for _ in 0..18 {
            p2.ai_style2(&w, &npcs, None, &mut rng, 0.0);
        }
        assert_eq!(p2.vel.y, 0.0, "no gravity before tick 20");
        p2.ai_style2(&w, &npcs, None, &mut rng, 0.0);
        assert!((p2.vel.y - 0.3).abs() < 1e-6);
        assert!((p2.vel.x - 4.0 * 0.98).abs() < 1e-6);
    }

    /// `:23520-23556` — the spark family: alpha pinned at 255, the fade-out
    /// kill at tick 60 (the kill does not return — the gravity tail runs),
    /// the +0.1/0.99 fall past tick 20. The dust window's `Next(100)` roll
    /// is skipped with the dust.
    #[test]
    fn s1_d_4b_8_the_spark_fades_out_at_sixty() {
        let w = world();
        for kind in [504u16, 954, 979] {
            let mut p = just(kind);
            p.vel = Vec2::new(4.0, 0.0);
            let mut rng = CountingRng::new();
            for _ in 0..59 {
                tick(&mut p, &w, &mut rng);
            }
            assert!(p.active, "kind {kind}: alive at 59");
            assert_eq!(p.alpha, 255);
            assert_eq!(rng.ranges, 0, "kind {kind}: the dust roll is skipped");
            tick(&mut p, &w, &mut rng);
            assert!(!p.active, "kind {kind}: the tick-60 kill");
            assert!(p.vel.y > 0.0, "kind {kind}: the gravity tail still ran");
        }
    }

    /// `:23659-23680` — the type-93 tail: the delay re-rolls every tick
    /// (`28 + Next(6)`), the threshold pins `ai[0] = 40`, and the five
    /// rising kinds aim at `atan2 + 1.57`. RNG: one draw per tick, always.
    #[test]
    fn s1_d_4b_8_the_93_rerolls_its_delay_every_tick() {
        let w = world();
        let mut p = just(93);
        p.vel = Vec2::new(3.0, -4.0);
        let mut rng = CountingRng::new();
        for i in 1..=40 {
            tick(&mut p, &w, &mut rng);
            assert_eq!(rng.ranges, i, "one draw per tick");
            if p.ai[0] < 40.0 && i < 34 {
                let expect_rot = p.vel.y.atan2(p.vel.x) + 1.57;
                assert!((p.rot - expect_rot).abs() < 1e-4, "the rising aim");
            }
        }
        assert!(p.ai[0] >= 40.0, "the pin holds past the max delay 33");
        assert!(p.vel.y > -4.0, "the gravity kicked in");
    }

    /// `:23610-23631` — the 306: the 50/tick fade floored at 0 and the
    /// `atan2 + 0.785` aim; the arm owns no `ai[0]` counter.
    #[test]
    fn s1_d_4b_8_the_306_fades_without_an_age_counter() {
        let w = world();
        let mut p = just(306);
        p.alpha = 120;
        p.vel = Vec2::new(3.0, 4.0);
        let mut rng = CountingRng::new();
        tick(&mut p, &w, &mut rng);
        assert_eq!(p.alpha, 70);
        assert_eq!(p.ai[0], 0.0, "no age counter");
        let expect_rot = 4.0f32.atan2(3.0) + 0.785;
        assert!((p.rot - expect_rot).abs() < 1e-5);
        tick(&mut p, &w, &mut rng);
        assert_eq!(p.alpha, 20);
        tick(&mut p, &w, &mut rng);
        assert_eq!(p.alpha, 0, "floored");
    }

    /// `:23207-23210` — the wind head adds `windSpeedCurrent * 0.1` before
    /// anything else; `:23681-23684` — the 32 px/tick fall clamp.
    #[test]
    fn s1_d_4b_8_the_wind_head_and_the_fall_clamp() {
        let w = world();
        let mut p = just(SHURIKEN);
        p.vel = Vec2::new(0.0, 40.0);
        let mut rng = CountingRng::new();
        p.ai_style2(&w, &[], None, &mut rng, 2.0);
        assert!((p.vel.x - 0.2).abs() < 1e-6, "the wind head");
        assert_eq!(p.vel.y, 32.0, "the clamp");
    }
}

#[cfg(test)]
mod s1_d_4b_5c_tests {
    use super::*;

    fn world() -> World {
        World::new("t".into(), 512, 64)
    }

    fn just(kind: u16) -> Projectile {
        Projectile {
            active: true,
            kind,
            w: 6.0,
            h: 6.0,
            direction: 1,
            time_left: 18000,
            ..Default::default()
        }
    }

    /// One pool tick with the C#'s per-tick minion counters cleared
    /// (`Player.cs:28279-28281` — the port clears them in `world_sim`).
    fn step(
        pool: &mut ProjectilePool,
        w: &mut World,
        p: &mut crate::player::Player,
        npcs: &mut Vec<Npc>,
        rng: &mut tr_core::tile_light::FastRandom,
    ) {
        p.num_minions = 0;
        p.slots_minions = 0.0;
        pool.update(
            w,
            npcs,
            None,
            None,
            Some(p),
            YoyoInputs::default(),
            FlailInputs::default(),
            rng,
            0,
            true,
        );
    }

    /// The aiStyle-23 Flames Trap arm (`Projectile.cs:25863-25870`): the launch
    /// counter floors at 8 and `localAI[0]` counts up (the
    /// `Damage_CanDealDamage` gate `:12448` reads it), the life caps at 60 and
    /// the counter advances one per tick.
    #[test]
    fn s1_d_4b_5c_the_flames_trap_floors_and_counts_its_launch() {
        let mut p = just(FLAMES_TRAP);
        p.ai[0] = 0.0;
        let w = world();
        p.ai_eye_fire(&w);
        assert_eq!(p.ai[0], 9.0, ":25865-25868 floors 0 to 8, :25890 adds one");
        assert_eq!(p.local_ai[0], 1.0, ":25869 counts the launch");
        assert_eq!(p.time_left, 60, ":25871-25874 caps the life at 60");
        assert!((p.rot - 0.3).abs() < 1e-6, ":25934 spins 0.3 * direction");
    }

    /// The Eye Fire arm (`Projectile.cs:25875-25893`): without the trap's
    /// floor, a counter at 0 stays below 7 and only takes the plain `++`
    /// (`:25932`); the spin is direction-mirrored (`:25934`).
    #[test]
    fn s1_d_4b_5c_the_eye_fire_advances_the_plain_counter() {
        let mut p = just(EYE_FIRE);
        p.ai[0] = 0.0;
        p.direction = -1;
        let w = world();
        p.ai_eye_fire(&w);
        assert_eq!(p.ai[0], 1.0, ":25932 — the below-7 arm just counts");
        assert_eq!(p.local_ai[0], 0.0, "the Eye Fire does not count launches");
        assert!((p.rot + 0.3).abs() < 1e-6, ":25934 mirrors with direction");
    }

    /// The aiStyle-158 walk (`Projectile.cs:48770-48777`): 6 ticks per frame,
    /// wrapping at `projFrames - 1` (so the last frame is only reachable by
    /// the perch snap — the walk wraps before it).
    #[test]
    fn s1_d_4b_5c_the_baby_bird_walks_six_ticks_per_frame() {
        let mut pool = ProjectilePool::new();
        let mut w = world();
        let mut p = crate::player::Player::spawn(&w);
        p.baby_bird = true;
        // Spawn far enough from home (> 40, < 2000) that the walk arm runs and
        // no teleport/perch masks it. The spot must stay inside the world —
        // the out-of-world guard (`:16683-16703`) rescues a minion onto its
        // owner and skips the AI for that sub-step.
        let home = ai_158_home_location(&p, 0);
        let slot = pool
            .spawn_with_data_ai_owned(
                BABY_BIRD,
                0,
                home.x + 300.0,
                home.y + 300.0,
                0.0,
                0.0,
                10,
                1.0,
                0.0,
                0.0,
            )
            .unwrap();
        let mut rng = tr_core::tile_light::FastRandom::new(7);
        let mut npcs: Vec<Npc> = Vec::new();
        for _ in 0..5 {
            step(&mut pool, &mut w, &mut p, &mut npcs, &mut rng);
        }
        assert_eq!(pool.slots()[slot].frame, 0, "five ticks is not a frame yet");
        step(&mut pool, &mut w, &mut p, &mut npcs, &mut rng);
        assert_eq!(pool.slots()[slot].frame, 1, ":48770-48777 the sixth tick");
        assert_eq!(proj_frames(BABY_BIRD), 5, "Main.cs:8506 — five frames");
    }

    /// The keep-alive (`Projectile.cs:48760-48769`): a dead owner clears the
    /// flag, a live one pins `timeLeft = 2`.
    #[test]
    fn s1_d_4b_5c_the_baby_bird_pin_follows_the_buff_flag() {
        let mut rng = tr_core::tile_light::FastRandom::new(7);
        let mut npcs: Vec<Npc> = Vec::new();
        let mut w = world();
        let mut p = crate::player::Player::spawn(&w);
        p.baby_bird = true;
        let home = ai_158_home_location(&p, 0);
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai_owned(
                BABY_BIRD,
                0,
                home.x + 200.0,
                home.y,
                0.0,
                0.0,
                10,
                1.0,
                0.0,
                0.0,
            )
            .unwrap();
        step(&mut pool, &mut w, &mut p, &mut npcs, &mut rng);
        assert_eq!(
            pool.slots()[slot].time_left, 1,
            "the pin of 2 minus the tail's decrement (`:17201`)"
        );
        // The dead-owner arm clears the flag on the next tick.
        p.dead = true;
        step(&mut pool, &mut w, &mut p, &mut npcs, &mut rng);
        assert!(!p.baby_bird, ":48762-48765 the death clears the flag");
    }

    /// The perch snap (`Projectile.cs:48919-48927`): the bird's centre inside
    /// the `8 + |player.velocity|` band of the home spot with an upright
    /// player sits on the LAST frame, frozen, facing the owner.
    #[test]
    fn s1_d_4b_5c_the_baby_bird_perches_on_the_last_frame() {
        let mut pool = ProjectilePool::new();
        let mut w = world();
        let mut p = crate::player::Player::spawn(&w);
        p.baby_bird = true;
        p.facing = -1;
        let home = ai_158_home_location(&p, 0);
        // The C# sets `Center = vector2`, so spawn the box centred on home.
        let slot = pool
            .spawn_with_data_ai_owned(
                BABY_BIRD,
                0,
                home.x - 5.0,
                home.y - 5.0,
                1.0,
                0.0,
                10,
                1.0,
                0.0,
                0.0,
            )
            .unwrap();
        let mut rng = tr_core::tile_light::FastRandom::new(7);
        let mut npcs: Vec<Npc> = Vec::new();
        step(&mut pool, &mut w, &mut p, &mut npcs, &mut rng);
        let bird = &pool.slots()[slot];
        assert_eq!(bird.frame, 4, ":48922 the perch frame is projFrames - 1");
        assert_eq!(bird.direction, -1, ":48925 the owner's facing");
        assert_eq!(bird.sprite_direction, -1);
        assert_eq!(bird.rot, 0.0, ":48926 the perched rotation is zero");
        assert!(
            bird.vel.length() < 1e-6,
            ":48924 the perch freezes the velocity ({:?})",
            bird.vel
        );
        assert!(!bird.tile_collide, ":48852 the no-target arm flies freely");
    }

    /// The home spot (`Projectile.cs:48930-48988`): the headgear lift minus 2,
    /// the six-slot ring and the per-stack lift, all off
    /// `RotatedRelativePoint(MountedCenter)` minus the 21-px eye line.
    ///
    /// With the port's `gravDir = 1` and no mount, `home = Center + gfxOffY -
    /// (0, 21) + (0, headgear - 2)`.
    #[test]
    fn s1_d_4b_5c_the_home_spot_walks_the_ring_and_the_stack() {
        let w = world();
        let mut p = crate::player::Player::spawn(&w);
        p.facing = 1;
        p.body_frame = 0; // `offsets_player_headgear_y(0)` = 2
        let (cx, cy) = p.center();
        let top = cy - 21.0; // headgear 2 − 2 = 0

        // Slot 0: no ring offset and no stack.
        let h0 = ai_158_home_location(&p, 0);
        assert_eq!(h0, Vec2::new(cx.floor(), top.floor()), "slot 0");

        // Slot 1: `direction * 8` right, `-2` up (`:48965`).
        let h1 = ai_158_home_location(&p, 1);
        assert_eq!(h1, Vec2::new((cx + 8.0).floor(), (top - 2.0).floor()));

        // Slot 2: `direction * -10` (`:48968`).
        let h2 = ai_158_home_location(&p, 2);
        assert_eq!(h2.x, (cx - 10.0).floor(), ":48968 the -10 ring slot");

        // Slot 6 opens the second ring: `-16` more (`:48984`).
        let h6 = ai_158_home_location(&p, 6);
        assert_eq!(h6.y, (top - 16.0).floor(), ":48984 the per-stack lift");
    }

    /// The four reach helpers (`Projectile.cs:12400-12444`): the 1000-px cap
    /// alone refuses a far target, and open air clears the four sight lines.
    #[test]
    fn s1_d_4b_5c_the_reach_helpers_cap_at_1000px() {
        let w = world();
        let p = crate::player::Player::spawn(&w);
        let (pcx, pcy) = p.center();
        let pc = Vec2::new(pcx, pcy);
        let mut proj = just(BABY_BIRD);
        proj.w = 10.0;
        proj.h = 10.0;
        // The minion rides just off the owner — the C#'s `Distance` reads the
        // PROJECTILE for the own-body probe and the PLAYER for the melee one.
        proj.pos = Vec2::new(pcx + 30.0, pcy);
        proj.direction = 1;

        let near = {
            let mut n = Npc::new(NpcKind::Slime, pcx + 20.0, pcy - 8.0, 1, 0.0);
            n.max_hp = 40;
            n.hp = 40;
            n
        };
        let far = {
            let mut n = Npc::new(NpcKind::Slime, pcx + 1400.0, pcy, 1, 0.0);
            n.max_hp = 40;
            n.hp = 40;
            n
        };
        assert!(
            proj.can_hit_with_own_body(&w, &near),
            ":12419 the open-air shoulder line clears"
        );
        assert!(
            !proj.can_hit_with_own_body(&w, &far),
            ":12415 the 1000-px cap"
        );
        assert!(
            proj.can_hit_with_melee_weapon(&w, &near, Some(&p), pc),
            ":12406 the owner's box clears in open air"
        );
        assert!(
            !proj.can_hit_with_melee_weapon(&w, &far, Some(&p), pc),
            ":12402 the owner-side 1000-px cap"
        );
    }
}

#[cfg(test)]
mod s1_d_4b_6_tests {
    use super::*;
    use crate::npc::{Npc, NpcKind};
    use crate::player::Player;
    use tr_core::tile::Tile;

    fn world() -> tr_core::World {
        tr_core::World::new("t".into(), 64, 64)
    }

    fn rng() -> tr_core::tile_light::FastRandom {
        tr_core::tile_light::FastRandom::new(7)
    }

    fn player(w: &tr_core::World) -> Player {
        let mut p = Player::spawn(w);
        p.max_minions = 10;
        p.num_minions = 0;
        p.slots_minions = 0.0;
        p
    }

    fn spawn_at(pool: &mut ProjectilePool, kind: u16, x: f32, y: f32) -> usize {
        pool.spawn_with_data_ai_owned(kind, 0, x, y, 0.0, 0.0, 10, 1.0, 0.0, 0.0)
            .unwrap()
    }

    fn npc_at(kind: NpcKind, x: f32, y: f32) -> Npc {
        let mut n = Npc::new(kind, x, y, 1, 0.0);
        n.max_hp = 400;
        n.hp = 400;
        n
    }

    fn tick(pool: &mut ProjectilePool, w: &mut tr_core::World, p: &mut Player, npcs: &mut [Npc]) {
        p.num_minions = 0;
        p.slots_minions = 0.0;
        pool.update(
            w,
            npcs,
            None,
            None,
            Some(p),
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut rng(),
            0,
            true,
        );
    }

    /// The three rows' `SetDefaults` slice (`Projectile.cs:4698-4741`,
    /// `:5997-6012`): the boxes, the aiStyle-66 family and the immunity split
    /// (the twins are idStatic, the Deadly Sphere is local, the 389 is stock).
    #[test]
    fn s1_d_4b_6_the_three_rows_carry_the_csharp_set_defaults() {
        for kind in [RETANIMINI, SPAZMAMINI] {
            let d = proj_data(kind).unwrap();
            assert_eq!((d.w, d.h), (40.0, 20.0), "kind {kind}");
            assert_eq!(d.ai_style, 66, "kind {kind}");
            assert_eq!(d.penetrate, -1, "kind {kind}");
            assert_eq!(d.time_left, 18000, "the `timeLeft *= 5`");
            assert!(d.minion, "kind {kind}");
            assert_eq!(d.minion_slots, 0.5, "kind {kind}");
            assert!(!d.tile_collide, "kind {kind}");
            assert!(d.ignore_water, "kind {kind}");
            assert!(d.uses_id_static_immunity, "kind {kind}");
            assert!(!d.uses_local_immunity, "kind {kind}");
            assert!(!d.net_important || d.minion, "kind {kind}");
        }
        let ret = proj_data(RETANIMINI).unwrap();
        assert_eq!(ret.id_static_hit_cooldown, 16, "`:4712`");
        let spa = proj_data(SPAZMAMINI).unwrap();
        assert_eq!(spa.id_static_hit_cooldown, 12, "`:4728`");

        let sphere = proj_data(DEADLY_SPHERE).unwrap();
        assert_eq!((sphere.w, sphere.h), (20.0, 20.0));
        assert_eq!(sphere.ai_style, 66);
        assert_eq!(sphere.penetrate, -1);
        assert_eq!(sphere.time_left, 18000);
        assert!(sphere.minion);
        assert_eq!(sphere.minion_slots, 1.0, "a full slot, not the twins' half");
        assert!(!sphere.tile_collide);
        assert!(sphere.ignore_water);
        assert!(sphere.uses_local_immunity, "the 533 uses the LOCAL pair");
        assert_eq!(sphere.local_hit_cooldown, 12, "`:6011`");
        assert!(!sphere.uses_id_static_immunity);

        let bolt = proj_data(MINI_RETINA_LASER).unwrap();
        assert_eq!((bolt.w, bolt.h), (4.0, 4.0), "`:4732-4733`");
        assert_eq!(bolt.ai_style, 1, "the plain flight");
        assert_eq!(bolt.alpha, 255, "`:4737`");
        assert_eq!(bolt.extra_updates, 2, "`:4738`");
        assert_eq!(bolt.scale, 1.2, "`:4739`");
        assert_eq!(bolt.time_left, 600, "`:4740`");
    }

    /// `:29617-29624` — the keep-alive pin: a live `twinsMinion` flag pins
    /// `timeLeft = 2`; a dead owner clears the flag (no pin).
    #[test]
    fn s1_d_4b_6_the_twins_pin_against_the_summon_flag() {
        let mut pool = ProjectilePool::new();
        let mut w = world();
        let mut p = player(&w);
        p.twins_minion = true;
        let (cx, cy) = p.center();
        let slot = spawn_at(&mut pool, RETANIMINI, cx - 150.0, cy);
        let mut npcs: Vec<Npc> = Vec::new();
        tick(&mut pool, &mut w, &mut p, &mut npcs);
        assert_eq!(
            pool.slots[slot].time_left, 1,
            "the pin of 2 minus the tail's per-tick decrement (`:17201`)"
        );
        // The dead owner clears the flag; the slot then lives on its counter.
        p.dead = true;
        pool.slots[slot].time_left = 18000;
        tick(&mut pool, &mut w, &mut p, &mut npcs);
        assert!(!p.twins_minion, "the dead owner drops the flag");
        assert_eq!(pool.slots[slot].time_left, 17999, "no pin after the clear");
    }

    /// `:29642-29669` — the same-type separation: the twins push each other
    /// apart as one family (a 387 and a 388 repel each other), the Deadly
    /// Sphere only against its own kind, and only inside `width` manhattan.
    #[test]
    fn s1_d_4b_6_the_twins_separate_from_each_other() {
        let mut pool = ProjectilePool::new();
        let (cx, cy) = (400.0f32, 400.0f32);
        let a = spawn_at(&mut pool, RETANIMINI, cx, cy);
        let b = spawn_at(&mut pool, SPAZMAMINI, cx + 20.0, cy);
        // Equal Y takes the `else` arm (`+0.05`), so a both-equal axis still
        // pushes — the C# compares with `<`, not `<=` (`:29660`).
        let sep = pool.slots[a].twins_separation(&pool.slots, a);
        assert_eq!(sep, Vec2::new(-0.05, 0.05), "the 388 is to the right");
        let sep_b = pool.slots[b].twins_separation(&pool.slots, b);
        assert_eq!(sep_b, Vec2::new(0.05, 0.05), "the 387 is to the left");
        // Beyond `width` (40 manhattan) there is no push.
        pool.slots[b].pos.x = cx + 60.0;
        assert_eq!(pool.slots[a].twins_separation(&pool.slots, a), Vec2::ZERO);
        // The Deadly Sphere ignores the twins and repels its own kind.
        pool.slots[b].active = false;
        let c = spawn_at(&mut pool, DEADLY_SPHERE, cx, cy);
        let d = spawn_at(&mut pool, DEADLY_SPHERE, cx, cy + 10.0);
        let sep_c = pool.slots[c].twins_separation(&pool.slots, c);
        assert_eq!(sep_c, Vec2::new(0.05, -0.05), "the 533 is below");
        assert_eq!(
            pool.slots[a].twins_separation(&pool.slots, a),
            Vec2::ZERO,
            "the spawner 533 does not push the twin"
        );
        pool.slots[c].pos.y = cy + 40.0;
        let _ = d;
    }

    /// `:29881-29900` — the pursue blend: with a target and state 0 the twins
    /// steer at `(v*40 + dir*speed) / 41`. The Retanimini's speed is 6, the
    /// Spazmamini's 14; inside 200 px the direction flips (`-4`).
    #[test]
    fn s1_d_4b_6_the_pursue_blend_uses_the_per_kind_speed() {
        let mut pool = ProjectilePool::new();
        let mut w = world();
        let mut p = player(&w);
        p.twins_minion = true;
        let (cx, cy) = p.center();
        // The NPC sits on the owner's centre; the twin spawns 700 px below, so
        // the scan finds it (`num510 < 2000`), the 388's 500 px charge gate
        // stays shut and the 200 px inner flip does not apply.
        let mut npcs = vec![npc_at(NpcKind::Zombie, cx, cy)];
        for kind in [RETANIMINI, SPAZMAMINI] {
            let slot = spawn_at(&mut pool, kind, cx - 20.0, cy + 700.0);
            let start = pool.slots[slot].vel;
            let center = pool.slots[slot].pos + Vec2::new(20.0, 10.0);
            let aim = npc_center(&npcs[0]);
            let dir = (aim - center).normalize_or_zero();
            let speed = if kind == SPAZMAMINI { 14.0 } else { 6.0 };
            let expected = (start * 40.0 + dir * speed) / 41.0;
            tick(&mut pool, &mut w, &mut p, &mut npcs);
            let vel = pool.slots[slot].vel;
            assert!(
                (vel.x - expected.x).abs() < 1e-3 && (vel.y - expected.y).abs() < 1e-3,
                "kind {kind}: vel={vel:?} expected≈{expected:?}"
            );
            assert!(vel.y < 0.0, "kind {kind} steers at the target above");
            pool.slots[slot].active = false;
        }
    }

    /// `:30111-30123` — the Spazmamini's charge entry: a target inside 500 px
    /// with a clear line flips `ai[0]` to 2, sets the velocity at 8 and runs
    /// the intercept. The next tick's charge arm counts the 40-tick timer and
    /// drops back to the follow state.
    #[test]
    fn s1_d_4b_6_the_spazmamini_charges_for_forty_ticks() {
        let mut pool = ProjectilePool::new();
        let mut w = world();
        let mut p = player(&w);
        p.twins_minion = true;
        let (cx, cy) = p.center();
        let mut npcs = vec![npc_at(NpcKind::Zombie, cx + 300.0, cy)];
        let slot = spawn_at(&mut pool, SPAZMAMINI, cx - 50.0, cy);
        tick(&mut pool, &mut w, &mut p, &mut npcs);
        assert_eq!(pool.slots[slot].ai[0], 2.0, "the charge state engaged");
        assert_eq!(pool.slots[slot].ai[1], 1.0, "the cooldown armed");
        assert_eq!(
            pool.slots[slot].extra_updates, 0,
            "the engage tick does not set the speedup (`:30111-30123`)"
        );
        // The charge arm (`:29682-29709`) runs on the next tick: it raises the
        // speedup to 1 and starts the 40-tick counter.
        tick(&mut pool, &mut w, &mut p, &mut npcs);
        assert_eq!(pool.slots[slot].extra_updates, 1, "the charge doubles");
        // 40 charge ticks later the state returns to 0.
        for _ in 0..40 {
            tick(&mut pool, &mut w, &mut p, &mut npcs);
            if pool.slots[slot].ai[0] == 0.0 {
                break;
            }
        }
        assert_eq!(pool.slots[slot].ai[0], 0.0, "the charge ends");
        // The reset arms `ai[1] = 1` and the same frame's `ai[1]` rolls
        // (`:30068-30071`) run twice (`extraUpdates = 1`), so the counter lands
        // in 1 + 2×(1..3).
        let cd = pool.slots[slot].ai[1];
        assert!((1.0..=7.0).contains(&cd), "the counter restarts ({cd})");
        assert_eq!(pool.slots[slot].extra_updates, 0, "the speedup drops");
    }

    /// `:30093-30109` — the Retanimini fires the 389 bolt at its target with
    /// the interrupt damage (×1.15) and the 300-tick life.
    #[test]
    fn s1_d_4b_6_the_retanimini_fires_the_bolts() {
        let mut pool = ProjectilePool::new();
        let mut w = world();
        let mut p = player(&w);
        p.twins_minion = true;
        let (cx, cy) = p.center();
        let mut npcs = vec![npc_at(NpcKind::Zombie, cx + 300.0, cy)];
        let slot = spawn_at(&mut pool, RETANIMINI, cx - 50.0, cy);
        // The bolt damage is the minion's 10 × 1.15 → 11 (the `(int)` cast).
        tick(&mut pool, &mut w, &mut p, &mut npcs);
        let bolt = (0..pool.slots.len())
            .find(|&i| i != slot && pool.slots[i].active && pool.slots[i].kind == MINI_RETINA_LASER)
            .expect("the 387 fired the 389");
        assert_eq!(pool.slots[bolt].damage, 11, "10 × 1.15 truncated");
        // The bolt lives in a later slot, so the same frame's ascending pass
        // reaches it and its `extraUpdates = 2` spends three sub-steps
        // (`:17197-17209`): 300 - 3.
        assert_eq!(pool.slots[bolt].time_left, 297, "the 300 override, this frame's 3 sub-steps");
        assert!(pool.slots[bolt].vel.x > 0.0, "the bolt flies at the target");
        assert_eq!(pool.slots[slot].ai[1], 1.0, "the 387's cooldown armed");
    }

    /// `Utils.GetChaseResults`/`SolveQuadratic` (`Utils.cs:645-728`): the
    /// straight-line case (a still runner) gives the arrival time; a near
    /// runner the quadratic root; an unreachable one yields `None`.
    #[test]
    fn s1_d_4b_6_the_intercept_maths_matches_the_csharp() {
        // A still runner 30 px away at speed 6: 5 ticks.
        let still = get_chase_results(Vec2::ZERO, 6.0, Vec2::new(30.0, 0.0), Vec2::ZERO).unwrap();
        assert!((still.interception_time - 5.0).abs() < 1e-4);
        assert!((still.chaser_velocity.x - 6.0).abs() < 1e-4);
        // A faster runner running away: no root crosses 0 both negative → None.
        let away = get_chase_results(Vec2::ZERO, 6.0, Vec2::new(30.0, 0.0), Vec2::new(10.0, 0.0));
        assert!(away.is_none(), "the chaser cannot catch a 10-speed runner");
        // A slower runner is caught.
        let ok = get_chase_results(Vec2::ZERO, 10.0, Vec2::new(30.0, 0.0), Vec2::new(2.0, 0.0));
        assert!(ok.is_some());
        let t = ok.unwrap().interception_time;
        assert!(t > 0.0 && t < 10.0, "the intercept lands in range ({t})");
        // The degenerate zero discriminant (`b²-4ac == 0`): a double root.
        let (r1, r2) = solve_quadratic(1.0, -2.0, 1.0).expect("one root");
        assert_eq!((r1, r2), (1.0, 1.0));
        assert!(solve_quadratic(1.0, 0.0, 1.0).is_none(), "negative disc");
    }

    /// `:29833-29861` — the scan excludes unchaseable NPCs (a town Guide) and
    /// picks the nearest chaseable one.
    #[test]
    fn s1_d_4b_6_the_scan_skips_uncraseable_targets() {
        let mut pool = ProjectilePool::new();
        let mut w = world();
        let mut p = player(&w);
        p.twins_minion = true;
        let (cx, cy) = p.center();
        let mut guide = npc_at(NpcKind::Guide, cx + 100.0, cy);
        guide.max_hp = 250;
        guide.hp = 250;
        let zombie = npc_at(NpcKind::Zombie, cx + 300.0, cy);
        let mut npcs = vec![guide, zombie];
        let slot = spawn_at(&mut pool, RETANIMINI, cx - 50.0, cy);
        tick(&mut pool, &mut w, &mut p, &mut npcs);
        // The bolt only fires at a chaseable target — the Guide is skipped.
        let fired = (0..pool.slots.len())
            .any(|i| i != slot && pool.slots[i].active && pool.slots[i].kind == MINI_RETINA_LASER);
        assert!(fired, "the zombie is a valid target past the Guide");
    }
}

#[cfg(test)]
mod projectile_ai_tests {
    //! The projectile-ai task's own fixtures: the aiStyle-2 thrown family
    //! (`Projectile.cs:23205-23688`) and the aiStyle-4 Vilethorn chain
    //! (`:23694-23828`) flown tick by tick against the C# numbers.

    use super::*;
    use tr_core::tile::{Tile, FLAG_ACTIVE};

    /// A world with no tiles at all — the flights under test never touch one
    /// unless the test says so.
    fn empty(width: i32, height: i32) -> World {
        World::new("t".into(), width, height)
    }

    /// [`empty`] with the dirt floor the other modules use: solid from row 30
    /// down.
    fn ground() -> World {
        let mut w = World::new("t".into(), 64, 64);
        for x in 0..64 {
            for y in 30..64 {
                let i = w.index(x, y);
                w.tiles[i] = Tile {
                    kind: 1,
                    ..Default::default()
                };
                w.tiles[i].flags |= FLAG_ACTIVE;
            }
        }
        w.spawn_x = 20;
        w.spawn_y = 20;
        w.compute_column_surface();
        w.compute_chunks();
        w
    }

    fn step(pool: &mut ProjectilePool, w: &mut World) {
        let mut rng = tr_core::tile_light::FastRandom::new(7);
        let mut npcs: Vec<Npc> = Vec::new();
        pool.update(
            w,
            &mut npcs,
            None,
            None,
            None,
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut rng,
            0,
            false,
        );
    }

    fn ticks(pool: &mut ProjectilePool, w: &mut World, n: usize) {
        for _ in 0..n {
            step(pool, w);
        }
    }

    // --- aiStyle 2: the thrown family (`Projectile.cs:23205-23688`).

    /// t1 — the shuriken's (type 3) C# trajectory over 20 ticks: the default
    /// arm's 20-tick gravity delay (`:23659-23674`), then `velocity.Y += 0.4f`
    /// and `velocity.X *= 0.97f` once, with the rotation ladder
    /// `(|vx| + |vy|) * 0.03f * direction` (`:23253-23256`) every tick.
    #[test]
    fn projectile_ai_style2_position_after_n_ticks() {
        let mut w = empty(64, 64);
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_owned(SHURIKEN, 0, 100.0, 100.0, 6.0, 2.0, 10, 0.0, 0.0, 0.0)
            .expect("the shuriken row (`Projectile.cs:828-836`)");
        pool.slots[slot].direction = 1;
        ticks(&mut pool, &mut w, 20);
        let p = &pool.slots[slot];
        assert!(p.active, "the shuriken is still in flight");
        // 19 straight ticks of (6, 2), then the 20th applies the friction.
        assert!((p.pos.x - 219.82).abs() < 0.01, "x = {}", p.pos.x);
        assert!((p.pos.y - 140.4).abs() < 0.01, "y = {}", p.pos.y);
        assert!((p.rot - 4.8).abs() < 0.01, "rot = {}", p.rot);
    }

    /// t2 — the constants of the default arm: the velocity is untouched for
    /// 19 ticks, `velocity.Y += 0.4f` / `velocity.X *= 0.97f` on the 20th
    /// (`:23659-23674`), and the `velocity.Y > 32f` clamp (`:23681-23684`)
    /// holds the fall at 32 px/tick.
    #[test]
    fn projectile_ai_style2_gravity_bounce() {
        let mut w = empty(64, 200);
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_owned(SHURIKEN, 0, 100.0, 8.0, 6.0, 0.0, 10, 0.0, 0.0, 0.0)
            .expect("the shuriken row");
        ticks(&mut pool, &mut w, 19);
        assert_eq!(pool.slots[slot].vel.y, 0.0, "no gravity before tick 20");
        assert_eq!(pool.slots[slot].vel.x, 6.0, "and no friction");
        step(&mut pool, &mut w);
        assert!((pool.slots[slot].vel.y - 0.4).abs() < 1e-6, "the +0.4 tick");
        assert!(
            (pool.slots[slot].vel.x - 5.82).abs() < 1e-5,
            "the 0.97 friction, x = {}",
            pool.slots[slot].vel.x
        );
        ticks(&mut pool, &mut w, 100);
        assert_eq!(pool.slots[slot].vel.y, 32.0, "the 32 px/tick clamp");
    }

    /// t3 — the thrown family dies on the first solid tile, one last step in:
    /// the movement chain's default arm (`:19849-19853`, `position +=
    /// velocity; Kill()`) — a shuriken does not bounce.
    #[test]
    fn projectile_ai_style2_dies_on_tile() {
        let mut w = ground();
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_owned(SHURIKEN, 0, 100.0, 400.0, 0.0, 6.0, 10, 0.0, 0.0, 0.0)
            .expect("the shuriken row");
        ticks(&mut pool, &mut w, 20);
        let p = &pool.slots[slot];
        assert!(!p.active, "the dirt row kills the shuriken");
        assert_eq!(p.vel.y, 6.0, "and the velocity never reverses");
        assert!(p.pos.y > 458.0, "the last step lands in the tile");
    }

    // --- aiStyle 4: the Vilethorn chain (`Projectile.cs:23694-23828`).

    /// t1 — the base's (type 7) chain: five ticks of fading at `alpha -= 50`
    /// (`:23714`), then `ai[0] = 1` (`:23728`), `ai[1] = 1` (`:23729`),
    /// `position += velocity` (`:23732`) and the child spawn at
    /// `position + velocity + (w/2, h/2)` (`:23734-23745`), whose `ai[1]` is
    /// the parent's plus one.
    #[test]
    fn projectile_ai_style4_position_after_n_ticks() {
        let mut w = empty(64, 64);
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_owned(VILE_BASE, 0, 100.0, 100.0, 32.0, 0.0, 20, 0.0, 0.0, 0.0)
            .expect("the Vilethorn row (`Projectile.cs:874-884`)");
        ticks(&mut pool, &mut w, 6);
        let parent = &pool.slots[slot];
        assert!(parent.active, "the base still fades");
        assert!((parent.pos.x - 324.0).abs() < 1e-4, "x = {}", parent.pos.x);
        assert_eq!(parent.ai[0], 1.0, "the segment is spent");
        assert_eq!(parent.ai[1], 1.0, "the depth counter");
        let child = pool
            .slots()
            .iter()
            .find(|p| p.kind == VILE_BASE && p.ai[1] == 2.0)
            .expect("the child segment");
        assert!((child.pos.x - 370.0).abs() < 1e-4, "x = {}", child.pos.x);
        assert!((child.pos.y - 114.0).abs() < 1e-4, "y = {}", child.pos.y);
        assert_eq!(child.alpha, 205, "the child's own fade");
    }

    /// t2 — the Vilethorn constants: no gravity, no bounce (`tileCollide =
    /// false`, `:874-884`), the `atan2 + 1.57` orientation (`:23706`), the
    /// `alpha -= 50` fade-in (`:23714`) and the `alpha += 5` fade-out that
    /// kills at 255 (`:23823-23828`).
    #[test]
    fn projectile_ai_style4_gravity_bounce() {
        let mut w = empty(64, 64);
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_owned(VILE_BASE, 0, 100.0, 100.0, 32.0, 0.0, 20, 0.0, 0.0, 0.0)
            .expect("the Vilethorn row");
        ticks(&mut pool, &mut w, 5);
        let p = &pool.slots[slot];
        assert_eq!(p.vel.y, 0.0, "no gravity");
        assert_eq!(p.vel.x, 32.0, "and no friction");
        assert_eq!(p.alpha, 5, "255 - 5 * 50");
        // The C# adds the literal `1.57f` (`:23723`), not pi/2.
        assert!((p.rot - 1.57).abs() < 1e-6, "atan2 + 1.57, {}", p.rot);
        ticks(&mut pool, &mut w, 52);
        assert!(
            !pool.slots[slot].active,
            "the +5 fade reaches 255 and kills"
        );
    }

    /// t3 — the segment does NOT die on a tile: `tileCollide = false`
    /// (`Projectile.cs:874-884`) is what lets the vine grow through walls.
    #[test]
    fn projectile_ai_style4_dies_on_tile() {
        let mut w = ground();
        let mut pool = ProjectilePool::new();
        // Buried in the dirt row (rows 30+), flying right.
        let slot = pool
            .spawn_with_data_owned(VILE_BASE, 0, 100.0, 500.0, 32.0, 0.0, 20, 0.0, 0.0, 0.0)
            .expect("the Vilethorn row");
        ticks(&mut pool, &mut w, 6);
        assert!(pool.slots[slot].active, "the vine ignores the tile");
        assert!(
            (pool.slots[slot].pos.x - 324.0).abs() < 1e-4,
            "and flies on, x = {}",
            pool.slots[slot].pos.x
        );
    }
}

/// S1-D-5 — the dungeon-debris trio 736/737/738 (`AI_010`,
/// `Projectile.cs:57826-58100`, the `:7748-7755` rows, the
/// `Kill_ExplodeTiles` death arm `:77369-77385`). Tests-as-code: written,
/// not run (the task's code-only mode).
#[cfg(test)]
mod s1_d_5_debris_tests {
    use super::*;
    use tr_core::tile::{FLAG_ACTIVE, Tile};

    /// The scripted stream: records every `(min, max)` draw and replays the
    /// roll list in order (the `DodgeScript` shape; an exhausted list reads
    /// `max - 1`).
    struct DebrisScript {
        rolls: Vec<i32>,
        draws: Vec<(i32, i32)>,
    }
    impl DebrisScript {
        fn with_rolls(rolls: &[i32]) -> Self {
            Self {
                rolls: rolls.to_vec(),
                draws: Vec::new(),
            }
        }
    }
    impl tr_core::loot::DropRng for DebrisScript {
        fn next_range(&mut self, min: i32, max: i32) -> i32 {
            self.draws.push((min, max));
            if self.rolls.is_empty() {
                return max - 1;
            }
            self.rolls.remove(0)
        }
        fn next_float(&mut self) -> f32 {
            0.5
        }
    }

    fn world() -> tr_core::World {
        let mut w = tr_core::World::new("t".into(), 64, 64);
        w.compute_column_surface();
        w.compute_chunks();
        w
    }

    fn put(w: &mut tr_core::World, x: i32, y: i32, kind: u16) {
        let i = w.index(x, y);
        w.tiles[i] = Tile {
            kind,
            flags: FLAG_ACTIVE,
            ..Tile::default()
        };
    }

    fn tick(
        pool: &mut ProjectilePool,
        w: &mut tr_core::World,
        npcs: &mut [Npc],
        player: Option<&mut crate::player::Player>,
        rng: &mut dyn tr_core::loot::DropRng,
    ) {
        pool.update(
            w,
            npcs,
            None,
            None,
            player,
            YoyoInputs::default(),
            FlailInputs::default(),
            rng,
            0,
            true,
        );
    }

    /// The three rows' `SetDefaults` slice (`Projectile.cs:7748-7755`): the
    /// 10x10 box, aiStyle 10, `penetrate = -1`, the stock timeLeft/extraUpdates/
    /// tileCollide, and the 3-frame sheets (`Main.cs:8445-8447`).
    #[test]
    fn s1_d_5_the_three_rows_carry_the_csharp_set_defaults() {
        for kind in DUNGEON_DEBRIS {
            let d = proj_data(kind).unwrap();
            assert_eq!((d.w, d.h), (10.0, 10.0), "kind {kind}");
            assert_eq!(d.ai_style, 10, "kind {kind}");
            assert_eq!(d.penetrate, -1, "kind {kind}");
            assert_eq!(d.time_left, TIME_LEFT_DEFAULT, "kind {kind}");
            assert_eq!(d.extra_updates, 0, "kind {kind}");
            assert!(d.tile_collide, "kind {kind}");
            assert!(!d.arrow && !d.trap, "kind {kind}");
            assert!(!d.uses_local_immunity && !d.uses_id_static_immunity, "kind {kind}");
            assert_eq!(d.alpha, 0, "kind {kind}");
            assert_eq!(d.scale, 1.0, "kind {kind}");
            assert_eq!(proj_frames(kind), 3, "kind {kind}");
        }
    }

    /// The first tick (`:57942-57950`): the `Next(40)` dust gate, the
    /// `Next(3)` frame roll and the `Next(30)` scale roll draw in that order;
    /// the owner's `ai[0] = 1` latch (`:57993`) drops `tileCollide` for the
    /// tick (`:57955`) and the 0.41 gravity (`:58019`) lands.
    #[test]
    fn s1_d_5_the_first_tick_rolls_the_frame_and_scale() {
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai(BLUE_DUNGEON_DEBRIS, 320.0, 100.0, 0.0, 0.0, 20, 0.0, 0.0, 0.0)
            .unwrap();
        let mut w = world();
        let mut rng = DebrisScript::with_rolls(&[7, 2, 10]);
        tick(&mut pool, &mut w, &mut [], None, &mut rng);
        assert_eq!(rng.draws, vec![(0, 40), (0, 3), (0, 30)], "the roll order");
        let p = &pool.slots[slot];
        assert_eq!(p.frame, 2, "the frame roll");
        assert!((p.scale - 0.9).abs() < 1e-6, "the scale roll: {}", p.scale);
        assert_eq!(p.local_ai[0], 1.0, "the one-shot latch");
        assert_eq!(p.ai[0], 1.0, "the owner's fall latch");
        assert!(!p.tile_collide, "the first tick's tileCollide drop");
        assert!(!p.friendly, "the stock friendly = false held");
        assert!((p.vel.y - 0.41).abs() < 1e-6, "the first gravity step");
        assert!((p.pos.y - 100.41).abs() < 1e-4, "the free first move");
    }

    /// The fall (`:58019`): +0.41/tick in mode 1, capped at 10 (`:58087-58090`).
    #[test]
    fn s1_d_5_the_fall_gravity_caps_at_ten() {
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai(GREEN_DUNGEON_DEBRIS, 320.0, 100.0, 0.0, 0.0, 20, 0.0, 0.0, 0.0)
            .unwrap();
        let mut w = world();
        for _ in 0..30 {
            tick(&mut pool, &mut w, &mut [], None, &mut tr_core::tile_light::FastRandom::new(7));
        }
        let p = &pool.slots[slot];
        assert!(p.active, "the empty world lets it fall");
        assert_eq!(p.ai[0], 1.0, "still the fall mode");
        assert!((p.vel.y - 10.0).abs() < 1e-6, "the 10 cap: {}", p.vel.y);
        assert!(p.pos.y > 100.0, "it fell");
    }

    /// The per-frame rotation (`:58073-58086`): frame 0 spins −0.1/tick,
    /// frame 1 +0.1, frame 2 +0.15.
    #[test]
    fn s1_d_5_the_rotation_follows_the_frame() {
        for (frame_roll, step) in [(0, -0.1f32), (1, 0.1), (2, 0.15)] {
            let mut pool = ProjectilePool::new();
            let slot = pool
                .spawn_with_data_ai(PINK_DUNGEON_DEBRIS, 320.0, 100.0, 0.0, 0.0, 20, 0.0, 0.0, 0.0)
                .unwrap();
            let mut w = world();
            let mut rng = DebrisScript::with_rolls(&[1, frame_roll, 0]);
            tick(&mut pool, &mut w, &mut [], None, &mut rng);
            assert_eq!(pool.slots[slot].frame, frame_roll);
            assert!(
                (pool.slots[slot].rot - step).abs() < 1e-6,
                "frame {frame_roll}: rot {}",
                pool.slots[slot].rot
            );
            let mut rng = DebrisScript::with_rolls(&[1]);
            tick(&mut pool, &mut w, &mut [], None, &mut rng);
            assert!(
                (pool.slots[slot].rot - 2.0 * step).abs() < 1e-6,
                "the spin accumulates"
            );
        }
    }

    /// The trio damages nothing: the C# stock `friendly = false`/`hostile =
    /// false` refuses `Damage_PVE_Inner` (`:12611`) and `Damage_EVP`
    /// (`:14775`) — an overlapping NPC and player both keep their HP, and
    /// the shard does not die on contact (the port's `damage_player` proxy
    /// is kind-gated).
    #[test]
    fn s1_d_5_the_debris_damages_nothing() {
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai(BLUE_DUNGEON_DEBRIS, 320.0, 100.0, 0.0, 0.0, 20, 0.0, 0.0, 0.0)
            .unwrap();
        let mut w = world();
        let mut npcs = vec![Npc::new(NpcKind::Slime, 320.0, 100.0, 1, 0.0)];
        npcs[0].max_hp = 400;
        npcs[0].hp = 400;
        let mut player = crate::player::Player::spawn(&w);
        player.x = 320.0;
        player.y = 100.0;
        let hp = player.hp;
        for _ in 0..3 {
            tick(&mut pool, &mut w, &mut npcs, Some(&mut player), &mut tr_core::tile_light::FastRandom::new(7));
        }
        assert_eq!(npcs[0].hp, 400, "the PVE refusal");
        assert_eq!(player.hp, hp, "the EVP refusal");
        assert!(pool.slots[slot].active, "no contact kill");
    }

    /// The owner's tile walk (`:58038-58072`): skipped on the first tick
    /// (the `tileCollide` drop), then the breakables die and a top slope
    /// flattens with the 16 px lift.
    #[test]
    fn s1_d_5_the_tile_walk_breaks_piles_and_flattens_slopes() {
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai(BLUE_DUNGEON_DEBRIS, 320.0, 300.0, 0.0, 0.0, 20, 0.0, 0.0, 0.0)
            .unwrap();
        let mut w = world();
        put(&mut w, 20, 19, 185); // a small pile in the box's second tick
        put(&mut w, 20, 18, 1);
        let i = w.index(20, 18);
        w.tiles[i].set_slope(1); // a top slope above it
        let mut rng = DebrisScript::with_rolls(&[1, 0, 0]);
        tick(&mut pool, &mut w, &mut [], None, &mut rng);
        assert!(w.tile(20, 19).unwrap().active(), "the first tick skips the walk");
        let mut rng = DebrisScript::with_rolls(&[1]);
        tick(&mut pool, &mut w, &mut [], None, &mut rng);
        assert!(!w.tile(20, 19).unwrap().active(), "the pile broke");
        let t = w.tile(20, 18).unwrap();
        assert_eq!(t.slope(), 0, "the slope flattened");
        assert!(!t.half_brick(), "the half brick cleared");
        assert!(pool.slots[slot].pos.y < 300.0, "the 16 px lift");
    }

    /// The death crack roll (`:77376-77385`): the tile below the centre, an
    /// active cracked brick, breaks on `Next(2) == 0`; a 1 keeps it, and a
    /// non-cracked tile never draws.
    #[test]
    fn s1_d_5_the_death_crack_roll_breaks_the_brick_below() {
        // The shard falls onto the brick at (20, 30): the blocked move kills
        // it (`:19849-19853`), the death hook rolls the brick below its centre.
        let mut pool = ProjectilePool::new();
        pool.spawn_with_data_ai(BLUE_DUNGEON_DEBRIS, 320.0, 470.0, 0.0, 0.0, 20, 0.0, 0.0, 0.0)
            .unwrap();
        let mut w = world();
        put(&mut w, 20, 30, 481);
        let mut rng = DebrisScript::with_rolls(&[1, 0, 0, 1, 0]);
        tick(&mut pool, &mut w, &mut [], None, &mut rng);
        tick(&mut pool, &mut w, &mut [], None, &mut rng);
        assert!(!w.tile(20, 30).unwrap().active(), "the 0 roll breaks the brick");
        assert_eq!(
            rng.draws,
            vec![(0, 40), (0, 3), (0, 30), (0, 40), (0, 2)],
            "the crack roll draws last"
        );

        // The 1 roll keeps the brick.
        let mut pool = ProjectilePool::new();
        pool.spawn_with_data_ai(GREEN_DUNGEON_DEBRIS, 320.0, 470.0, 0.0, 0.0, 20, 0.0, 0.0, 0.0)
            .unwrap();
        let mut w = world();
        put(&mut w, 20, 30, 482);
        let mut rng = DebrisScript::with_rolls(&[1, 0, 0, 1, 1]);
        tick(&mut pool, &mut w, &mut [], None, &mut rng);
        tick(&mut pool, &mut w, &mut [], None, &mut rng);
        assert!(w.tile(20, 30).unwrap().active(), "the 1 roll keeps the brick");

        // A plain stone below: the short-circuit never draws the crack roll.
        let mut pool = ProjectilePool::new();
        pool.spawn_with_data_ai(PINK_DUNGEON_DEBRIS, 320.0, 470.0, 0.0, 0.0, 20, 0.0, 0.0, 0.0)
            .unwrap();
        let mut w = world();
        put(&mut w, 20, 30, 1);
        let mut rng = DebrisScript::with_rolls(&[1, 0, 0, 1]);
        tick(&mut pool, &mut w, &mut [], None, &mut rng);
        tick(&mut pool, &mut w, &mut [], None, &mut rng);
        assert!(w.tile(20, 30).unwrap().active(), "the stone stays");
        assert_eq!(rng.draws, vec![(0, 40), (0, 3), (0, 30), (0, 40)], "no crack draw");
    }
}

#[cfg(test)]
mod lights_bane_tests {
    //! S1-G-3: the Light's Bane slash (974) — the SetDefaults row, the
    //! aiStyle-188 frame machine and `DrawProj_LightsBane`'s batch layout
    //! (`Projectile.cs:9237-9252`, `:42229-42262`, `Main.cs:27455-27495`).
    use super::*;

    fn world() -> World {
        World::new("t".into(), 512, 64)
    }

    fn spawn(pool: &mut ProjectilePool) -> usize {
        pool.spawn_with_data_owned(LIGHTS_BANE, 0, 100.0, 100.0, 8.0, 0.0, 20, 0.0, 1.0, 0.0)
            .expect("the LightsBane row")
    }

    fn ticks(pool: &mut ProjectilePool, w: &mut World, n: usize) {
        let mut rng = tr_core::tile_light::FastRandom::new(7);
        let mut npcs: Vec<Npc> = Vec::new();
        for _ in 0..n {
            pool.update(
                w,
                &mut npcs,
                None,
                None,
                None,
                YoyoInputs::default(),
                FlailInputs::default(),
                &mut rng,
                0,
                false,
            );
        }
    }

    /// The SetDefaults row (`Projectile.cs:9237-9252`): 20x20, aiStyle 188,
    /// penetrate 2, timeLeft 30, tileCollide off, ignoreWater on, the
    /// local-immunity pair (true, −1).
    #[test]
    fn the_set_defaults_row_matches_the_csharp() {
        let d = proj_data(LIGHTS_BANE).expect("the row exists");
        assert_eq!((d.w, d.h), (20.0, 20.0));
        assert_eq!(d.ai_style, 188);
        assert_eq!(d.penetrate, 2);
        assert_eq!(d.time_left, 30);
        assert!(!d.tile_collide);
        assert!(d.ignore_water);
        assert!(d.uses_local_immunity);
        assert_eq!(d.local_hit_cooldown, -1);
        // The drawer's own 13-row slice is NOT the projFrames table — 974
        // keeps the loop default 1 (`Main.cs:8439-8442`, no override row).
        assert_eq!(proj_frames(LIGHTS_BANE), 1);
        assert!(spawnable_kinds().contains(&LIGHTS_BANE), "the sheet packs");
    }

    /// `AI_188_LightsBane` (`Projectile.cs:42240-42251`): the scale latches
    /// `ai[0]`, the frame advances every third tick, the rotation follows the
    /// velocity. The pool's `timeLeft = 30` (`:9249`) kills the slash at tick
    /// 30 — before the frame machine's own frame-12 kill at tick 36, which
    /// the arm test below pins directly.
    #[test]
    fn the_frame_machine_advances_every_third_tick() {
        let mut w = world();
        let mut pool = ProjectilePool::new();
        let slot = spawn(&mut pool);
        ticks(&mut pool, &mut w, 1);
        let p = &pool.slots[slot];
        assert_eq!(p.scale, 1.0, "scale = ai[0]");
        assert_eq!(p.frame, 0);
        assert_eq!(p.frame_counter, 1);
        assert_eq!(p.local_ai[0], 1.0);
        assert!((p.rot - 0.0).abs() < 1e-6, "velocity (8, 0) → rot 0");
        assert!((p.pos.x - 108.0).abs() < 1e-4, "flies on, no tile collide");
        ticks(&mut pool, &mut w, 2);
        assert_eq!(pool.slots[slot].frame, 1, "the third tick advances");
        assert_eq!(pool.slots[slot].frame_counter, 0);
        // The 30-tick life (`Projectile.cs:9249`): tick 29 still flies at
        // frame 9, tick 30 spends the last timeLeft and kills.
        ticks(&mut pool, &mut w, 26);
        assert!(pool.slots[slot].active);
        assert_eq!(pool.slots[slot].frame, 9);
        ticks(&mut pool, &mut w, 1);
        assert!(!pool.slots[slot].active, "timeLeft 30 kills");
    }

    /// The arm's own kill (`Projectile.cs:42245-42248`): the twelfth frame
    /// kills the slash — reachable when the life counter is refreshed (the
    /// C# keeps both gates).
    #[test]
    fn the_twelfth_frame_kills_the_slash() {
        let w = world();
        let mut p = Projectile {
            active: true,
            kind: LIGHTS_BANE,
            frame: 11,
            frame_counter: 2,
            ..Default::default()
        };
        p.ai_lights_bane(&w);
        assert!(!p.active, "frame 12 kills");
        assert_eq!(p.time_left, 0);
        assert_eq!(p.frame, 12);
    }

    /// `Main.cs:27483-27492` — the eight quads: two stretched ghosts of row
    /// 12 (`White * 0.3f * num`), four White copies of the current frame, all
    /// multiply; then two Magenta copies, additive. The order is the C#'s
    /// push order — the batch boundaries the port's blend runs reproduce.
    #[test]
    fn the_batch_layout_matches_the_csharp_draw_order() {
        let b = lights_bane_batches(6);
        // num at frame 6: Remap(6,0,3)=1, Remap(6,4,12,1,0)=1−2/8=0.75.
        // The tint is TWO byte truncations: (byte)(255*0.3)=76, then
        // (byte)(76*0.75)=57 — NOT the fused 0.3*0.75=0.225.
        let ghost = 57.0 / 255.0;
        assert_eq!(b[0], (tr_render::BlendMode::Multiply, [1.0, 6.0], 12, [ghost, ghost, ghost, ghost]));
        assert_eq!(b[1], (tr_render::BlendMode::Multiply, [2.0, 2.0], 12, [ghost, ghost, ghost, ghost]));
        for q in &b[2..6] {
            assert_eq!(*q, (tr_render::BlendMode::Multiply, [1.0, 1.0], 6, [1.0, 1.0, 1.0, 1.0]));
        }
        for q in &b[6..8] {
            assert_eq!(*q, (tr_render::BlendMode::Additive, [1.0, 1.0], 6, [1.0, 0.0, 1.0, 1.0]));
        }
        // The ghost window: num is 0 at frame 0 and back to 0 at frame 12
        // (`:27480`'s two remaps), peaking over frames 3..4.
        assert_eq!(lights_bane_batches(0)[0].3, [0.0; 4]);
        assert_eq!(lights_bane_batches(12)[0].3, [0.0; 4]);
        // The peak is 76/255 — `(byte)(255*0.3)` — not 0.3.
        assert_eq!(lights_bane_batches(3)[0].3, [76.0 / 255.0; 4]);
    }

    /// The XNA two-step byte quantisation of `Color.White * 0.3f * num`
    /// (`Main.cs:27483-27484`): `Color.operator*(Color, float)` truncates
    /// every channel (alpha included) to a byte on EACH multiply, so the
    /// chain stores `(byte)(255f * 0.3f) = 76` first and `(byte)(76f * num)`
    /// second. Fusing `0.3 * num` into one float drifts up to 1 LSB — frame
    /// 6 must be 57/255, not 0.225. Pins the byte ladder over the ghost
    /// window; expected values derived from the C# expression, never from
    /// the port.
    #[test]
    fn the_ghost_tint_truncates_twice_like_xna() {
        // num = Remap(f,0,3,0,1) * Remap(f,4,12,1,0); byte = (byte)(76*num).
        // f=0: 0*1 → 0; f=2: (2/3)*1 → (byte)50.666 = 50; f=3..4: 1 → 76;
        // f=6: 1*0.75 → 57; f=8: 1*0.5 → 38; f=10: 1*0.25 → 19; f=12: 0.
        for (frame, byte) in [(0, 0.0), (2, 50.0), (3, 76.0), (4, 76.0), (6, 57.0), (8, 38.0), (10, 19.0), (12, 0.0)] {
            let t = lights_bane_batches(frame)[0].3;
            assert_eq!(t, [byte / 255.0; 4], "frame {frame}: (byte)(76*num) = {byte}");
        }
        // The fused float would give 0.225 at frame 6 — 0.375 LSB away.
        let fused = 0.3f32 * 0.75;
        let stored = lights_bane_batches(6)[0].3[0];
        assert!((stored - fused).abs() > 1e-6, "not the fused 0.3*num");
        // Both ghosts carry the same tint (the two `:27483-27484` draws).
        assert_eq!(lights_bane_batches(6)[0].3, lights_bane_batches(6)[1].3);
    }

    /// The screen placement (`Main.cs:27474-27492`): every quad's pivot
    /// lands on the C#'s `position` anchor — `pos` is the UNROTATED
    /// top-left `anchor − origin` and `origin` is the frame half scaled by
    /// the PER-QUAD scale vector (XNA multiplies the texture-space origin
    /// by the scale, so the `(1, 6)`/`(2, 2)` ghosts stretch their pivots
    /// too). Mirrors the `palm_placement` precedent: a synthetic sheet
    /// pins the maths without a GPU.
    #[test]
    fn the_quads_place_the_origin_texel_on_the_anchor() {
        // A 20x260 sheet = thirteen 20x20 rows; half = (10, 10).
        let sheet = tr_render::SheetRect {
            x: 0,
            y: 0,
            width: 20,
            height: 260,
            plain_frame: (0, 0),
        };
        let atlas = (512u32, 512u32);
        let anchor = [100.0, 200.0];
        // scale 1, zoom 1: s = 0.7, the base quad is 14x14, origin (7, 7).
        let q = lights_bane_quads(&sheet, atlas, 6, 1.0, anchor, 1.0);
        let near = |a: [f32; 2], b: [f32; 2]| {
            assert!((a[0] - b[0]).abs() < 1e-4 && (a[1] - b[1]).abs() < 1e-4, "{a:?} vs {b:?}");
        };
        // Ghost 1: stretch (1, 6) → size (14, 84), origin (7, 42).
        near(q[0].origin, [7.0, 42.0]);
        near(q[0].pos, [93.0, 158.0]);
        near(q[0].size, [14.0, 84.0]);
        // Ghost 2: stretch (2, 2) → size (28, 28), origin (14, 14).
        near(q[1].origin, [14.0, 14.0]);
        near(q[1].pos, [86.0, 186.0]);
        near(q[1].size, [28.0, 28.0]);
        // The six unstretched copies: origin (7, 7), pos = anchor − origin.
        for quad in &q[2..8] {
            near(quad.origin, [7.0, 7.0]);
            near(quad.pos, [93.0, 193.0]);
            near(quad.size, [14.0, 14.0]);
        }
        // Every pivot lands on the anchor — the helper's `pos + origin`
        // invariant (`push_ui_sprite_blend` shifts by `origin − R·origin`).
        for quad in &q {
            near([quad.pos[0] + quad.origin[0], quad.pos[1] + quad.origin[1]], anchor);
        }
        // The ghosts sample row 12 (`:27481`'s `value`), the copies the
        // current frame (`:27477`'s `rectangle`).
        let uv12 = frame_slice_uv(&sheet, atlas, 12, 13);
        let uv6 = frame_slice_uv(&sheet, atlas, 6, 13);
        assert_eq!(q[0].uv, uv12);
        assert_eq!(q[1].uv, uv12);
        for quad in &q[2..8] {
            assert_eq!(quad.uv, uv6);
        }
        // scale 2, zoom 1.5: s = 0.7*2*1.5 = 2.1 — the origin scales with
        // the quad (XNA's origin·scale), the ghosts' stretches included.
        let q = lights_bane_quads(&sheet, atlas, 6, 2.0, anchor, 1.5);
        near(q[0].origin, [21.0, 126.0]);
        near(q[0].pos, [79.0, 74.0]);
        near(q[0].size, [42.0, 252.0]);
        near(q[1].origin, [42.0, 42.0]);
        near(q[1].pos, [58.0, 158.0]);
        near(q[2].origin, [21.0, 21.0]);
        near(q[2].pos, [79.0, 179.0]);
        for quad in &q {
            near([quad.pos[0] + quad.origin[0], quad.pos[1] + quad.origin[1]], anchor);
        }
    }
}

#[cfg(test)]
mod s1_d_4b_7_tests {
    use super::*;
    use crate::npc::{Npc, NpcKind};
    use crate::player::Player;

    fn world() -> tr_core::World {
        tr_core::World::new("t".into(), 64, 64)
    }

    fn rng() -> tr_core::tile_light::FastRandom {
        tr_core::tile_light::FastRandom::new(7)
    }

    fn player(w: &tr_core::World) -> Player {
        let mut p = Player::spawn(w);
        p.max_minions = 10;
        p.num_minions = 0;
        p.slots_minions = 0.0;
        p.facing = 1;
        p
    }

    fn spawn_at(pool: &mut ProjectilePool, kind: u16, x: f32, y: f32) -> usize {
        pool.spawn_with_data_ai_owned(kind, 0, x, y, 0.0, 0.0, 10, 1.0, 0.0, 0.0)
            .unwrap()
    }

    fn npc_at(kind: NpcKind, x: f32, y: f32) -> Npc {
        let mut n = Npc::new(kind, x, y, 1, 0.0);
        n.max_hp = 400;
        n.hp = 400;
        n
    }

    fn tick(pool: &mut ProjectilePool, w: &mut tr_core::World, p: &mut Player, npcs: &mut [Npc]) {
        p.num_minions = 0;
        p.slots_minions = 0.0;
        pool.update(
            w,
            npcs,
            None,
            None,
            Some(p),
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut rng(),
            0,
            true,
        );
    }

    /// A draw-recording `Main.rand` stand-in: `next_range` returns `min`
    /// (the burst comparison never resets, the frog's `Next(50)` roll hits
    /// 0), `next_float` returns 0 — the census proves count AND order.
    struct CensusRng {
        ranges: Vec<(i32, i32)>,
        floats: usize,
    }

    impl tr_core::loot::DropRng for CensusRng {
        fn next_range(&mut self, min: i32, max: i32) -> i32 {
            self.ranges.push((min, max));
            min
        }
        fn next_float(&mut self) -> f32 {
            self.floats += 1;
            0.0
        }
    }

    /// The four rows' `SetDefaults` slice (`Projectile.cs:4755-4768`,
    /// `:7814-7828`) + the frame sheets (`Main.cs:8518-8520`, `:8631`).
    #[test]
    fn s1_d_4b_7_the_four_rows_carry_the_csharp_set_defaults() {
        for kind in [ONE_EYED_PIRATE, SOULSCOURGE_PIRATE, PIRATE_CAPTAIN] {
            let d = proj_data(kind).unwrap();
            assert_eq!((d.w, d.h), (20.0, 30.0), "kind {kind}");
            assert_eq!(d.ai_style, 67, "kind {kind}");
            assert_eq!(d.penetrate, -1, "kind {kind}");
            assert_eq!(d.time_left, 18000, "the `timeLeft *= 5`");
            assert!(d.minion, "kind {kind}");
            assert_eq!(d.minion_slots, 1.0, "kind {kind}");
            assert!(d.tile_collide, "the stock true — the arm sets neither");
            assert!(!d.ignore_water, "kind {kind}");
            assert!(d.uses_local_immunity, "the LOCAL pair (`:4765`)");
            assert_eq!(d.local_hit_cooldown, 18, "`:4766`");
            assert!(!d.uses_id_static_immunity, "kind {kind}");
            assert!(d.decides_manual_fall_through, "`:4767`");
            assert_eq!(proj_frames(kind), 15, "Main.cs:8518-8520");
        }
        let frog = proj_data(VAMPIRE_FROG).unwrap();
        assert_eq!((frog.w, frog.h), (20.0, 30.0));
        assert_eq!(frog.ai_style, 67);
        assert_eq!(frog.penetrate, -1);
        assert_eq!(frog.time_left, 18000);
        assert!(frog.minion);
        assert_eq!(frog.minion_slots, 1.0);
        assert!(frog.uses_id_static_immunity, "the idStatic pair (`:7826`)");
        assert_eq!(frog.id_static_hit_cooldown, 10, "`:7827`");
        assert!(!frog.uses_local_immunity);
        assert!(frog.decides_manual_fall_through, "`:7825`");
        assert_eq!(proj_frames(VAMPIRE_FROG), 24, "Main.cs:8631");
    }

    /// Per-type dispatch: each ported kind's slot moves on its first tick
    /// (the walk's gravity `:51144` + the integrate), while the deferred
    /// Storm Tiger row stays inert — the dispatch gates it.
    #[test]
    fn s1_d_4b_7_the_dispatch_arms_the_pirates_and_the_frog() {
        let mut pool = ProjectilePool::new();
        let mut w = world();
        let mut p = player(&w);
        let (cx, cy) = p.center();
        let mut npcs: Vec<Npc> = Vec::new();
        for kind in [ONE_EYED_PIRATE, SOULSCOURGE_PIRATE, PIRATE_CAPTAIN, VAMPIRE_FROG] {
            let slot = spawn_at(&mut pool, kind, cx + 60.0, cy);
            tick(&mut pool, &mut w, &mut p, &mut npcs);
            let s = &pool.slots[slot];
            assert!(s.active, "kind {kind} lives");
            assert!(s.pos.y > cy, "kind {kind} fell — the arm ran ({:?})", s.pos);
            assert!(s.vel.x < 0.0, "kind {kind} walks home (left)");
            pool.slots[slot].active = false;
        }
        // The deferred types: the row exists (aiStyle 67) but the dispatch
        // gate leaves the slot inert until their arms land.
        let tiger = spawn_at(&mut pool, STORM_TIGER_1, cx + 60.0, cy);
        tick(&mut pool, &mut w, &mut p, &mut npcs);
        assert_eq!(pool.slots[tiger].pos, Vec2::new(cx + 60.0, cy));
        assert_eq!(pool.slots[tiger].vel, Vec2::ZERO);
    }

    /// `:49248-49259` / `:49316-49327` — the keep-alive pins: a live summon
    /// flag pins `timeLeft = 2`; a dead owner clears the flag (no pin).
    #[test]
    fn s1_d_4b_7_the_pirates_and_frog_pin_against_their_summon_flags() {
        let mut pool = ProjectilePool::new();
        let mut w = world();
        let mut p = player(&w);
        let (cx, cy) = p.center();
        let mut npcs: Vec<Npc> = Vec::new();
        p.pirate_minion = true;
        p.vampire_frog = true;
        let pirate = spawn_at(&mut pool, ONE_EYED_PIRATE, cx - 150.0, cy);
        let frog = spawn_at(&mut pool, VAMPIRE_FROG, cx + 150.0, cy);
        tick(&mut pool, &mut w, &mut p, &mut npcs);
        assert_eq!(pool.slots[pirate].time_left, 1, "the pin of 2 minus the tail's decrement");
        assert_eq!(pool.slots[frog].time_left, 1);
        p.dead = true;
        pool.slots[pirate].time_left = 18000;
        pool.slots[frog].time_left = 18000;
        tick(&mut pool, &mut w, &mut p, &mut npcs);
        assert!(!p.pirate_minion, "the dead owner drops the flag");
        assert!(!p.vampire_frog);
        assert_eq!(pool.slots[pirate].time_left, 17999, "no pin after the clear");
        assert_eq!(pool.slots[frog].time_left, 17999);
    }

    /// `:50216-50231` + `:49966-50057` — the frog bites a close target:
    /// `ai[0] = 2`, `ai[1] = 20`, the 20-tick bite counts down into the
    /// 60-tick cooldown (`ai[1] = -60`), and the cooldown's first tick
    /// resets to the follow state (`num10 >= 0`, `:49958-49964`).
    #[test]
    fn s1_d_4b_7_the_frog_bites_for_twenty_ticks_then_cools_down() {
        let mut pool = ProjectilePool::new();
        let mut w = world();
        let mut p = player(&w);
        let (cx, cy) = p.center();
        let slot = spawn_at(&mut pool, VAMPIRE_FROG, cx, cy);
        // The NPC's centre sits 40 px right of the frog's centre — inside
        // the frog's 50-px bite range (`num29`, `:50107-50111`).
        let frog_center = Vec2::new(cx + 10.0, cy + 15.0);
        let mut n = npc_at(NpcKind::Zombie, 0.0, 0.0);
        let (nw, nh) = n.size();
        n.x = frog_center.x + 40.0 - nw * 0.5;
        n.y = frog_center.y - nh * 0.5;
        let mut npcs = vec![n];
        tick(&mut pool, &mut w, &mut p, &mut npcs);
        assert_eq!(pool.slots[slot].ai[0], 2.0, "the bite armed");
        assert_eq!(pool.slots[slot].ai[1], 20.0, "`ai[1] = num10`");
        assert!(pool.slots[slot].friendly, "the frog is friendly (`:49587`)");
        for _ in 0..20 {
            tick(&mut pool, &mut w, &mut p, &mut npcs);
        }
        assert_eq!(pool.slots[slot].ai[1], -60.0, "the cooldown (`:50055`)");
        tick(&mut pool, &mut w, &mut p, &mut npcs);
        assert_eq!(pool.slots[slot].ai[0], 0.0, "the cooldown resets (`:49960-49961`)");
        assert_eq!(pool.slots[slot].ai[1], 0.0);
    }

    /// `:50058-50086` — the pirates' state-5 arrival: inside 2 strike steps
    /// the pirate snaps onto the ring point, arms the bite (`ai[1] = 15`)
    /// and the velocity's Y lands on -3 (the C#'s double write). RNG: the
    /// arrival draws exactly ONE `NextFloat` (the circular-edge angle).
    #[test]
    fn s1_d_4b_7_the_pirate_teleport_strike_arrives_with_one_float_draw() {
        let mut w = world();
        let mut p = player(&w);
        let (cx, cy) = p.center();
        let mut proj = Projectile {
            active: true,
            kind: PIRATE_CAPTAIN,
            owner: 0,
            w: 20.0,
            h: 30.0,
            pos: Vec2::new(cx, cy),
            ..Default::default()
        };
        proj.ai[0] = 5.0;
        let my_center = proj.pos + Vec2::new(10.0, 15.0);
        let mut n = npc_at(NpcKind::Zombie, 0.0, 0.0);
        let (nw, nh) = n.size();
        n.x = my_center.x + 20.0 - nw * 0.5;
        n.y = my_center.y - nh * 0.5;
        let npcs = vec![n];
        let mut census = CensusRng { ranges: Vec::new(), floats: 0 };
        proj.ai_freaking_pirates(&w, Some(&mut p), &npcs, &mut census);
        assert_eq!(proj.ai[0], 2.0, "the strike became a bite");
        assert_eq!(proj.ai[1], 15.0, "`ai[1] = num10` (the pirates' 15)");
        assert_eq!(proj.vel.y, -3.0, "the C#'s abs-then--3 double write");
        let num27 = nw.min(nh) * 0.5 * 0.5;
        let ring = npc_center(&npcs[0]) + Vec2::new(num27, 0.0);
        assert_eq!(proj.pos, ring - Vec2::new(10.0, 15.0), "the centre snap");
        assert_eq!(census.floats, 1, "one NextVector2CircularEdge draw");
        assert!(census.ranges.is_empty(), "no integer draws on the arrival");
    }

    /// RNG census, idle pirate (`:51150-51171`): exactly one
    /// `Next(900,1200)` comparison per tick, in order, nothing else — the
    /// dust/gore internals are skipped but the burst's gate stays.
    #[test]
    fn s1_d_4b_7_the_idle_pirate_draws_one_burst_comparison_per_tick() {
        let mut w = world();
        let mut p = player(&w);
        let (cx, cy) = p.center();
        let mut proj = Projectile {
            active: true,
            kind: ONE_EYED_PIRATE,
            owner: 0,
            w: 20.0,
            h: 30.0,
            pos: Vec2::new(cx + 100.0, cy),
            ..Default::default()
        };
        let mut census = CensusRng { ranges: Vec::new(), floats: 0 };
        for _ in 0..3 {
            proj.ai_freaking_pirates(&w, Some(&mut p), &[], &mut census);
        }
        assert_eq!(census.ranges, vec![(900, 1200); 3], "one comparison per tick");
        assert_eq!(census.floats, 0);
        assert_eq!(proj.local_ai[0], 3.0, "the counter climbs (vel.x != 0)");
    }

    /// RNG census, resting frog (`:51036-51050`): the blink's `Next(50)`
    /// draws ONLY when the frame counter reaches 28 (the `&&`
    /// short-circuit) — 27 silent ticks, the 28th draws, the 0-roll resets
    /// the counter and the 29th is silent again.
    #[test]
    fn s1_d_4b_7_the_frog_blink_draws_only_at_the_28th_tick() {
        let mut w = world();
        let mut p = player(&w);
        let (cx, cy) = p.center();
        // The home spot is cx - 45 (35 + width/2, facing 1); the line-walk
        // trim keeps the aim within the 5-px dead band, so vel.x stays 0.
        let mut proj = Projectile {
            active: true,
            kind: VAMPIRE_FROG,
            owner: 0,
            w: 20.0,
            h: 30.0,
            pos: Vec2::new(cx - 55.0, cy),
            ..Default::default()
        };
        let mut census = CensusRng { ranges: Vec::new(), floats: 0 };
        for i in 1..=29 {
            proj.vel = Vec2::ZERO;
            proj.ai_freaking_pirates(&w, Some(&mut p), &[], &mut census);
            if i < 28 {
                assert!(census.ranges.is_empty(), "tick {i}: the short-circuit holds");
            } else if i == 28 {
                assert_eq!(census.ranges, vec![(0, 50)], "the 28th tick draws");
                assert_eq!(proj.frame_counter, 0, "the 0-roll resets the blink");
            } else {
                assert_eq!(census.ranges.len(), 1, "tick {i}: silent again");
            }
        }
        assert_eq!(census.floats, 0);
    }
}
#[cfg(test)]
mod proj_light_spawn_tests {
    //! S1-E-5: the `light` amount's journey from `SetDefaults`
    //! (`set_defaults_light`) through the data-carrying spawn onto the slot,
    //! the aiStyle-24 per-tick rewrite (`Projectile.cs:25953`), and the
    //! stream-neutrality of the `proj_lights.rs` frame feed тАФ the feed is a
    //! pure read (`proj_light` takes no RNG), so interleaving it with the
    //! pool step cannot move `Main.rand`.
    use super::*;

    fn world() -> World {
        World::new("t".into(), 512, 64)
    }

    fn step(pool: &mut ProjectilePool, w: &mut World, rng: &mut tr_core::tile_light::FastRandom) {
        let mut npcs: Vec<Npc> = Vec::new();
        pool.update(
            w,
            &mut npcs,
            None,
            None,
            None,
            YoyoInputs::default(),
            FlailInputs::default(),
            rng,
            0,
            false,
        );
    }

    /// Feed every active slot through the frame-pass function тАФ the same
    /// call `app/frame/draw.rs` makes after the step.
    fn feed(pool: &ProjectilePool) -> Vec<(i32, i32, [f32; 3])> {
        let p = tr_core::lighting::LightParams::default();
        pool.slots()
            .iter()
            .filter(|s| s.active)
            .filter_map(|s| crate::proj_lights::proj_light(s.kind, s.light, s.pos, s.w, s.h, false, &p))
            .collect()
    }

    #[test]
    fn test_s1_e_5_the_spawn_copies_the_set_defaults_light() {
        // The data-carrying spawn (`spawn_with_data_ai_owned`) copies
        // `ProjData::light` тАФ the `SetDefaults` slice тАФ onto the slot.
        let mut pool = ProjectilePool::new();
        for (kind, want) in [
            (FLAME_ARROW, 1.0),      // `:824`
            (MUSKET_BALL, 0.5),      // `:957`
            (BULLET_SNOWMAN, 0.5),   // `:1985`
            (CRYSTAL_STORM, 0.5),    // `:1784`
            (DUAL_HOOK_BLUE, 0.4),   // `:1546`
            (ILLUMINANT_HOOK, 0.3),  // `:5631`
        ] {
            let slot = pool
                .spawn_with_data(kind, 160.0, 160.0, 1.0, 0.0, 10, 0.0)
                .unwrap_or_else(|| panic!("kind {kind} has a row"));
            assert_eq!(pool.slots()[slot].light, want, "kind {kind}");
            assert_eq!(pool.slots()[slot].light, set_defaults_light(kind));
            pool.kill(slot);
        }
        // An unlit row keeps the stock `0f` reset (`:773`).
        let slot = pool
            .spawn_with_data(BOMB, 160.0, 160.0, 1.0, 0.0, 10, 0.0)
            .unwrap();
        assert_eq!(pool.slots()[slot].light, 0.0);
        assert!(crate::proj_lights::proj_light(
            BOMB,
            pool.slots()[slot].light,
            pool.slots()[slot].pos,
            pool.slots()[slot].w,
            pool.slots()[slot].h,
            false,
            &tr_core::lighting::LightParams::default(),
        )
        .is_none());
    }

    #[test]
    fn test_s1_e_5_the_water_bolt_has_no_set_defaults_light() {
        // `Projectile.cs:1095-1105` тАФ the WaterBolt 27's `SetDefaults` arm
        // writes NO `this.light`, so the slot keeps the `0f` reset (`:773`)
        // and `ProjLight` early-returns: its `:16380-16385` colour arm is
        // unreachable until a later system writes the amount (the C# never
        // does тАФ the arm is dead code in the source too). The missing
        // `set_defaults_light` row is faithful, not a gap.
        assert_eq!(set_defaults_light(WATER_BOLT), 0.0);
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data(WATER_BOLT, 160.0, 160.0, 1.0, 0.0, 10, 0.0)
            .unwrap();
        assert_eq!(pool.slots()[slot].light, 0.0);
        let mut w = world();
        let mut rng = tr_core::tile_light::FastRandom::new(7);
        for _ in 0..10 {
            step(&mut pool, &mut w, &mut rng);
        }
        assert!(feed(&pool).is_empty(), "the water bolt stays dark");
    }

    #[test]
    fn test_s1_e_5_the_crystal_storm_light_follows_its_scale() {
        // `:25953` тАФ `this.light = this.scale * 0.5f` every tick, BEFORE the
        // fade (`:25962-25968`, from `ai[1] > 130f`). At the row's scale 1.2
        // the shard starts at 0.6; two fade ticks drop the scale to 1.1 and
        // the light to 0.55, and the frame feed reads the CURRENT amount.
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data(CRYSTAL_STORM, 160.0, 160.0, 1.0, 0.0, 20, 0.0)
            .unwrap();
        let mut w = world();
        let mut rng = tr_core::tile_light::FastRandom::new(7);
        step(&mut pool, &mut w, &mut rng);
        let p = &pool.slots()[slot];
        assert_eq!(p.light, p.scale * 0.5);
        assert_eq!(p.light, 1.2 * 0.5);
        for _ in 0..131 {
            step(&mut pool, &mut w, &mut rng);
        }
        let p = &pool.slots()[slot];
        assert_eq!(p.ai[1], 132.0, "two ticks past the fade gate");
        // The rewrite runs BEFORE the fade (`:25953` ahead of `:25962`), so
        // after a fade tick the light holds the PRE-fade scale's half.
        assert!(
            (p.light - (p.scale + 0.05) * 0.5).abs() < 1e-5,
            "the rewrite tracks the pre-fade scale"
        );
        let lit = crate::proj_lights::proj_light(
            p.kind,
            p.light,
            p.pos,
            p.w,
            p.h,
            false,
            &tr_core::lighting::LightParams::default(),
        )
        .expect("the shard still lights");
        // `:16283-16287` тАФ (0.5l, 0, l) off the faded amount.
        assert_eq!(lit.2, [p.light * 0.5, 0.0, p.light]);
    }

    #[test]
    fn test_s1_e_5_the_light_feed_leaves_the_rng_stream_untouched() {
        // The stream-neutrality witness: two identical runs тАФ one interleaves
        // the frame feed after every step, one never feeds тАФ must leave the
        // seeded `FastRandom` at the same state. `proj_light` is pure (no RNG
        // parameter; the rand-bearing 867/1000 chain arms have no rows), so
        // this holds by construction; the test pins it against a future arm
        // that tries to draw.
        let kinds = [FLAME_ARROW, MUSKET_BALL, CRYSTAL_STORM, DEMON_SCYTHE, WATER_BOLT];
        let mut seeds = Vec::new();
        for feed_lights in [false, true] {
            let mut pool = ProjectilePool::new();
            for (i, kind) in kinds.iter().enumerate() {
                pool.spawn_with_data(*kind, 160.0 + i as f32 * 32.0, 160.0, 2.0, -1.0, 10, 0.0)
                    .unwrap();
            }
            let mut w = world();
            let mut rng = tr_core::tile_light::FastRandom::new(7);
            for _ in 0..60 {
                step(&mut pool, &mut w, &mut rng);
                if feed_lights {
                    let _ = feed(&pool);
                }
            }
            seeds.push(rng.seed);
        }
        assert_eq!(seeds[0], seeds[1], "the feed cannot move the stream");
    }
}

#[cfg(test)]
mod s1_d_5_data_row_tests {
    //! S1-D-5 (`task/S1-D-5-projdata-deviations`, code-only mode — tests
    //! WRITTEN NOT RUN): the projectile data-row deviation fixes. (1) the
    //! spiky ball 185 rides its own aiStyle-14 row (`Projectile.cs
    //! :2717-2727`), not the dart group's aiStyle 1; (2) the duplicate
    //! unreachable `MUSKET_BALL` 10x10 arm is gone — kind 14 resolves the
    //! real 4x4 row (`:950-961`); (3) the same-id alias pairs
    //! (`SCRAMBLER_SHOT`/`BRAIN_SCRAMBLER` 436, `MARTIAN_RAY`/`RAY_GUNNER`
    //! 438, `LEAF`/`LEAF_BLOWER` 206) resolve ONE row each, while 462/622
    //! are DISTINCT C# ids with distinct rows; (4) the six dead dispatch
    //! arms (aiStyle 1/3/14/16/115/99) are deleted — the live arms still
    //! run (the 99 yoyo clock and the 14 spear flight pinned here).
    use super::*;

    fn world() -> World {
        World::new("t".into(), 64, 64)
    }

    fn step(pool: &mut ProjectilePool, w: &mut World) {
        let mut npcs: Vec<Npc> = Vec::new();
        pool.update(
            w,
            &mut npcs,
            None,
            None,
            None,
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut tr_core::tile_light::FastRandom::new(7),
            0,
            true,
        );
    }

    #[test]
    fn s1_d_5_the_spiky_ball_row_is_the_csharp_2717_arm() {
        // `Projectile.cs:2717-2727`: 14x14, aiStyle 14, penetrate -1,
        // timeLeft 900, trap. Before the fix the row rode the dart group
        // (10x10, aiStyle 1) — the slice-A gate never saw it, but the
        // generic arrow flight gave it the wrong gravity/rotation.
        let d = proj_data(TRAP_SPIKY_BALL).expect("the 185 row");
        assert_eq!((d.w, d.h), (14.0, 14.0), "`:2719-2720`");
        assert_eq!(d.ai_style, 14, "`:2721` — NOT the dart group's 1");
        assert_eq!(d.penetrate, -1, "`:2724`");
        assert_eq!(d.time_left, 900, "`:2725`");
        assert!(d.tile_collide);
        assert!(d.trap, "`:2726`");
        // The dart group keeps its own aiStyle-1 row without the 185.
        let dart = proj_data(TRAP_DART).expect("the dart row");
        assert_eq!(dart.ai_style, 1);
        assert_eq!((dart.w, dart.h), (10.0, 10.0));
    }

    #[test]
    fn s1_d_5_the_spiky_ball_dispatches_the_spear_flight() {
        // The 14 arm (`ai_spear`, `Projectile.cs:25143-25158`): ai[0]++
        // per tick, the `ai[0] > 5f` gravity `velocity.Y += 0.2f` from the
        // 6th tick, `rotation += velocity.X * 0.1f`. Under the old row the
        // ball ran `ai_arrow` (gravity 0.1 from tick 15) — this pins the
        // dispatch switch. The tile BOUNCE (`HandleMovement` `:19703-19713`)
        // is still unported: `ai_spear` kills on the tile scan — the
        // documented gap in ANALYSIS "The projectile data-row deviations".
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data(TRAP_SPIKY_BALL, 160.0, 160.0, 4.0, 0.0, 40, 2.0)
            .expect("the row spawns");
        let mut w = world();
        step(&mut pool, &mut w);
        let p = &pool.slots()[slot];
        assert_eq!(p.ai[0], 1.0, "the spear counter ticks (`:25144`)");
        assert_eq!(p.vel.y, 0.0, "no gravity before the 6th tick");
        assert!((p.rot - 0.4).abs() < 1e-5, "`rotation += 4 * 0.1` (`:25157`)");
        for _ in 0..5 {
            step(&mut pool, &mut w);
        }
        let p = &pool.slots()[slot];
        assert_eq!(p.ai[0], 5.0, "the counter caps at 5 (`:25147`)");
        assert!((p.vel.y - 0.2).abs() < 1e-5, "the 6th tick adds 0.2 (`:25155`)");
    }

    #[test]
    fn s1_d_5_kind_14_resolves_the_real_musket_ball_row() {
        // `Projectile.cs:950-961`: 4x4, aiStyle 1, penetrate 1, light 0.5,
        // alpha 255, scale 1.2, timeLeft 600, extraUpdates 1. The deleted
        // duplicate arm claimed 10x10/timeLeft 3600/extraUpdates 0 — it was
        // unreachable behind this row (the compiler only warned).
        let d = proj_data(MUSKET_BALL).expect("the 14 row");
        assert_eq!((d.w, d.h), (4.0, 4.0));
        assert_eq!(d.ai_style, 1);
        assert_eq!(d.time_left, 600);
        assert_eq!(d.extra_updates, 1);
        assert_eq!(d.penetrate, 1);
    }

    #[test]
    fn s1_d_5_the_alias_pairs_resolve_one_row_each() {
        // The C# has ONE id per pair (`ProjectileID.cs:1426` BrainScramblerBolt
        // = 436, `:1430` RayGunnerLaser = 438, `:966` Leaf = 206) — the Rust
        // alias consts stay for their callers, but `proj_data` carries one
        // arm per id. The deleted arms were unreachable duplicates.
        assert_eq!(SCRAMBLER_SHOT, BRAIN_SCRAMBLER);
        assert_eq!(MARTIAN_RAY, RAY_GUNNER);
        assert_eq!(LEAF, LEAF_BLOWER);
        assert_eq!(proj_data(SCRAMBLER_SHOT), proj_data(BRAIN_SCRAMBLER));
        assert_eq!(proj_data(MARTIAN_RAY), proj_data(RAY_GUNNER));
        assert_eq!(proj_data(LEAF), proj_data(LEAF_BLOWER));
        // The leaf row is the `:2937-2945` arm (both copies were
        // value-identical): 14x14, aiStyle 40, penetrate 1, timeLeft 360,
        // alpha 255.
        let leaf = proj_data(LEAF).expect("the 206 row");
        assert_eq!((leaf.w, leaf.h), (14.0, 14.0));
        assert_eq!(leaf.ai_style, 40);
        assert_eq!(leaf.time_left, 360);
        assert_eq!(leaf.alpha, 255);
    }

    #[test]
    fn s1_d_5_462_and_622_are_distinct_rows_with_the_csharp_alpha() {
        // NOT aliases: `ProjectileID.cs:1478` PhantasmalBolt = 462 and
        // `:1798` BlowupSmokeMoonlord = 622 are different ids with different
        // `SetDefaults` arms (`Projectile.cs:5329-5339` / `:6691-6698`).
        // Both set `alpha = 255`; the fix carries it (the bolt fades IN via
        // `:55660-55671`; the smoke never fades — invisible for its whole
        // life, the visible effect is the skipped dust 229).
        assert_ne!(PHANTASMAL_BOLT, BLOWUP_SMOKE_MOONLORD);
        let bolt = proj_data(PHANTASMAL_BOLT).expect("the 462 row");
        assert_eq!((bolt.w, bolt.h), (8.0, 8.0), "`:5331-5332`");
        assert_eq!(bolt.ai_style, 1);
        assert_eq!(bolt.extra_updates, 3, "`:5336`");
        assert!(!bolt.tile_collide, "`:5338`");
        assert_eq!(bolt.alpha, 255, "`:5335`");
        let smoke = proj_data(BLOWUP_SMOKE_MOONLORD).expect("the 622 row");
        assert_eq!((smoke.w, smoke.h), (10.0, 10.0), "`:6693-6694`");
        assert_eq!(smoke.ai_style, 1);
        assert_eq!(smoke.extra_updates, 2, "`:6697`");
        assert!(smoke.tile_collide);
        assert_eq!(smoke.alpha, 255, "`:6696`");
        // The martian pair is distinct too (436 vs 438): the scrambler has
        // no alpha write, the ray gunner's `:5087` sets 255.
        assert_ne!(proj_data(BRAIN_SCRAMBLER), proj_data(RAY_GUNNER));
        assert_eq!(proj_data(BRAIN_SCRAMBLER).unwrap().alpha, 0);
        assert_eq!(proj_data(RAY_GUNNER).unwrap().alpha, 255);
        assert_eq!(proj_data(RAY_GUNNER).unwrap().extra_updates, 3);
    }

    #[test]
    fn s1_d_5_the_ray_gunner_spawns_invisible_and_fades_in() {
        // The integration witness for the alpha fix: the data-carrying
        // spawn copies the row's 255, and the slice-A fade (`:55660-55671`,
        // `alpha -= (byte)(speed * 0.9)`) drops it `(byte)(10 * 0.9) = 9`
        // per sub-step. Under the old reset-0 row the fade was a no-op
        // (alpha stayed 0 — the fade-in state was lost from tick 1).
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_hostile(RAY_GUNNER, Vec2::new(160.0, 160.0), Vec2::new(10.0, 0.0), 30, 0.0)
            .expect("the row spawns");
        assert_eq!(pool.slots()[slot].alpha, 255, "the spawn copies `:5087`");
        let mut w = world();
        // extraUpdates 3 → 4 sub-steps per update; each fades 9:
        // 255 → 246 → 237 → 228 → 219.
        step(&mut pool, &mut w);
        assert_eq!(pool.slots()[slot].alpha, 219, "4 sub-steps × 9 off 255");
    }

    #[test]
    fn s1_d_5_the_live_yoyo_arm_still_ticks_after_the_dedupe() {
        // The dead duplicate `99 =>` arm (byte-identical to the live one)
        // is deleted; the LIVE arm's lifetime clock (`AI_099_2_Yoyos`
        // `:67745`, `localAI[0]++`) must still run through the dispatch.
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai_owned(CHIK_YOYO, 0, 160.0, 160.0, 0.0, 0.0, 20, 4.0, 0.0, 0.0)
            .expect("the yoyo row spawns");
        let mut w = world();
        step(&mut pool, &mut w);
        assert_eq!(pool.slots()[slot].local_ai[0], 1.0, "the 99 arm ran");
        step(&mut pool, &mut w);
        assert_eq!(pool.slots()[slot].local_ai[0], 2.0);
        assert!(pool.slots()[slot].active, "the keep-alive pins timeLeft 6");
    }
}

/// S1-P-i22 — the magic guns + tomes' projectile rows + AI arms (code-only
/// mode: tests WRITTEN NOT RUN). Every expected value is hand-derived from
/// the cited `Projectile.cs` lines; the dust/sound RNG is skipped pool-wide
/// (the S1-D-5 precedent), so the AI witnesses run on a fixed seed and the
/// only RNG draw is the Nettle Burst head's `Next(2)` flip.
#[cfg(test)]
mod s1_p_i22_magic_guns_tomes_tests {
    use super::*;
    use tr_core::tile::{FLAG_ACTIVE, Tile};

    fn world() -> World {
        World::new("t".into(), 128, 128)
    }

    fn step(pool: &mut ProjectilePool, w: &mut World) {
        let mut npcs: Vec<Npc> = Vec::new();
        pool.update(
            w,
            &mut npcs,
            None,
            None,
            None,
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut tr_core::tile_light::FastRandom::new(7),
            0,
            true,
        );
    }

    /// The 14 new rows carry their verbatim `SetDefaults` slices.
    #[test]
    fn s1_p_i22_the_rows_carry_the_csharp_set_defaults() {
        // 9 Starfury (`:886-896`): 24x24, aiStyle 5, pen 2, scale 0.8,
        // tileCollide false.
        let d = proj_data(STARFURY).expect("the 9 row");
        assert_eq!((d.w, d.h, d.ai_style, d.penetrate), (24.0, 24.0, 5, 2));
        assert!(!d.tile_collide);
        assert_eq!(d.scale, 0.8);
        // 76/77/78 notes (`:1556-1593`): aiStyle 21, pen 5, timeLeft 180,
        // alpha 100, local immunity 30; the per-kind box.
        for (k, w, h) in [(QUARTER_NOTE, 10.0, 22.0), (EIGHTH_NOTE, 18.0, 24.0), (TIED_EIGHTH_NOTE, 22.0, 24.0)] {
            let d = proj_data(k).expect("the note row");
            assert_eq!((d.w, d.h, d.ai_style, d.penetrate, d.time_left), (w, h, 21, 5, 180));
            assert_eq!(d.alpha, 100);
            assert!(d.uses_local_immunity);
            assert_eq!(d.local_hit_cooldown, 30);
        }
        // 150-152 nettle (`:2398-2410`): 28x28, aiStyle 4, pen -1,
        // tileCollide false, alpha 255.
        for k in [NETTLE_BURST_RIGHT, NETTLE_BURST_LEFT, NETTLE_BURST_END] {
            let d = proj_data(k).expect("the nettle row");
            assert_eq!((d.w, d.h, d.ai_style, d.penetrate), (28.0, 28.0, 4, -1));
            assert!(!d.tile_collide);
            assert_eq!(d.alpha, 255);
        }
        // 260 HeatRay (`:3441-3451`): 8x8, aiStyle 48, extraUpdates 100,
        // timeLeft 200, pen 1.
        let d = proj_data(HEAT_RAY).expect("the 260 row");
        assert_eq!((d.w, d.h, d.ai_style, d.extra_updates, d.time_left, d.penetrate), (8.0, 8.0, 48, 100, 200, 1));
        // 265 PoisonFang (`:3503-3515`): 12x12, aiStyle 1, alpha 255, pen 3,
        // local immunity 10, timeLeft 37.
        let d = proj_data(POISON_FANG).expect("the 265 row");
        assert_eq!((d.w, d.h, d.ai_style, d.penetrate, d.time_left), (12.0, 12.0, 1, 3, 37));
        assert_eq!(d.alpha, 255);
        assert!(d.uses_local_immunity);
        assert_eq!(d.local_hit_cooldown, 10);
        // 442 missile (`:5126-5136`): 14x14, aiStyle 1, alpha 255, timeLeft 600.
        let d = proj_data(ELECTROSPHERE_MISSILE).expect("the 442 row");
        assert_eq!((d.w, d.h, d.ai_style, d.time_left), (14.0, 14.0, 1, 600));
        assert_eq!(d.alpha, 255);
        // 443 sphere (`:5137-5149`): 80x80, aiStyle 77, pen -1, tileCollide
        // false, alpha 255.
        let d = proj_data(ELECTROSPHERE).expect("the 443 row");
        assert_eq!((d.w, d.h, d.ai_style, d.penetrate), (80.0, 80.0, 77, -1));
        assert!(!d.tile_collide);
        // 459 orb (`:5292-5303`): 22x22, aiStyle 1, alpha 255, extraUpdates 1.
        let d = proj_data(CHARGED_BLASTER_ORB).expect("the 459 row");
        assert_eq!((d.w, d.h, d.ai_style, d.extra_updates), (22.0, 22.0, 1, 1));
        // 460 holder (`:5304-5316`): 14x18, aiStyle 75, pen -1, tileCollide false.
        let d = proj_data(CHARGED_BLASTER_CANNON).expect("the 460 row");
        assert_eq!((d.w, d.h, d.ai_style, d.penetrate), (14.0, 18.0, 75, -1));
        assert!(!d.tile_collide);
        // 461 beam (`:5317-5328`): 18x18, aiStyle 84, pen -1, alpha 255,
        // tileCollide false.
        let d = proj_data(CHARGED_BLASTER_BEAM).expect("the 461 row");
        assert_eq!((d.w, d.h, d.ai_style, d.penetrate), (18.0, 18.0, 84, -1));
        assert!(!d.tile_collide);
        // 521 CrystalPulse (`:5908-5918`): 14x14, aiStyle 29, alpha 255,
        // pen 1, extraUpdates 1.
        let d = proj_data(CRYSTAL_PULSE).expect("the 521 row");
        assert_eq!((d.w, d.h, d.ai_style, d.penetrate, d.extra_updates), (14.0, 14.0, 29, 1, 1));
        // 856 SparkleGuitar (`:8206-8219`): 32x32, aiStyle 167, alpha 255,
        // tileCollide false, extraUpdates 2, local immunity -1.
        let d = proj_data(SPARKLE_GUITAR).expect("the 856 row");
        assert_eq!((d.w, d.h, d.ai_style, d.extra_updates), (32.0, 32.0, 167, 2));
        assert!(!d.tile_collide);
        assert!(d.uses_local_immunity);
        assert_eq!(d.local_hit_cooldown, -1);
        // 955 StarCannonStar (`:9013-9023`): 18x18, aiStyle 5, pen -1, alpha 50.
        let d = proj_data(STAR_CANNON_STAR).expect("the 955 row");
        assert_eq!((d.w, d.h, d.ai_style, d.penetrate), (18.0, 18.0, 5, -1));
        assert_eq!(d.alpha, 50);
    }

    /// The Crystal Pulse fades in at −50/sub-step (`:37733-37740`); with
    /// extraUpdates 1 that is 2 sub-steps per update: 255 → 155 after one.
    #[test]
    fn s1_p_i22_the_crystal_pulse_fades_in() {
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai_owned(CRYSTAL_PULSE, 0, 160.0, 160.0, 8.5, 0.0, 40, 4.4, 0.0, 0.0)
            .expect("the 521 row spawns");
        assert_eq!(pool.slots()[slot].alpha, 255, "the spawn copies `:5913`");
        let mut w = world();
        step(&mut pool, &mut w);
        assert_eq!(pool.slots()[slot].alpha, 155, "2 sub-steps × 50 off 255");
        step(&mut pool, &mut w);
        assert_eq!(pool.slots()[slot].alpha, 55);
        step(&mut pool, &mut w);
        assert_eq!(pool.slots()[slot].alpha, 0, "clamped at 0");
    }

    /// The Electrosphere Missile kills when it reaches the tile target
    /// (`:54742-54746`: Distance(Center, (ai0,ai1)·16+8) <= 16) and its death
    /// spawns the sphere 443 (`:73550`). The row's `extraUpdates` is 0 (the C#
    /// `:5126-5136` sets none), so ONE sub-step per update: the AI checks the
    /// arrival BEFORE the move (`kill_step` integrates after the arm), so the
    /// centre reads 176 + (n−1)·8 on update n — the arrival (dist ≤ 16 to
    /// 232) lands on update 6 (centre 216), not 5 (centre 208, dist 24).
    #[test]
    fn s1_p_i22_the_electrosphere_missile_arrival_spawns_the_sphere() {
        let mut pool = ProjectilePool::new();
        // The target tile (14, 10) → world (232, 168). The missile spawns at
        // x=169 (centre 176) flying +8/update: the centre reads 216 on update
        // 6 (176 + 5·8 = 216 — five moves precede the sixth check), distance
        // 16 → the arrival kill.
        let slot = pool
            .spawn_with_data_ai_owned(
                ELECTROSPHERE_MISSILE, 0, 169.0, 161.0, 8.0, 0.0, 40, 2.0, 14.0, 10.0,
            )
            .expect("the 442 row spawns");
        let mut w = world();
        for _ in 0..6 {
            step(&mut pool, &mut w);
        }
        assert!(!pool.slots()[slot].active, "the arrival kill");
        let sphere = pool
            .slots()
            .iter()
            .find(|p| p.active && p.kind == ELECTROSPHERE)
            .expect("the death spawns the sphere");
        assert_eq!(sphere.damage, 40, "the missile's damage");
        assert_eq!(sphere.knock_back, 0.0, "knockback 0 (`:73550`)");
    }

    /// The Nettle Burst head chains 150↔151 and tips to 152 at depth ≥ 10
    /// (`:23762-23781`); the fade-in is −75 (−50 −25, `:23714-23718`). The
    /// head's first-tick `Next(2)` flip (`:23709-23713`) makes the exact child
    /// kind RNG-dependent, so the witness asserts the chain DEPTH (robust to
    /// the flip) — the kind alternation is pinned by the C# cite.
    #[test]
    fn s1_p_i22_the_nettle_burst_chain_and_fade() {
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai_owned(NETTLE_BURST_RIGHT, 0, 160.0, 160.0, 32.0, 0.0, 35, 1.0, 0.0, 0.0)
            .expect("the 150 row spawns");
        let mut w = world();
        // The head's first tick: alpha 255 − 75 = 180 (still fading).
        step(&mut pool, &mut w);
        assert_eq!(pool.slots()[slot].alpha, 180, "the −75 fade-in");
        // Run to the chain: the head reaches alpha 0 at tick 4 (255−75·4<0),
        // flips ai0=1 and spawns the child.
        for _ in 0..5 {
            step(&mut pool, &mut w);
        }
        let child = pool
            .slots()
            .iter()
            .find(|p| p.active && p.ai[1] == 2.0 && matches!(p.kind, NETTLE_BURST_LEFT | NETTLE_BURST_RIGHT | NETTLE_BURST_END))
            .expect("the chain child");
        assert_eq!(child.ai[1], 2.0, "the depth counter");
    }

    /// The Sparkle Guitar note dies at localAI[0] ≥ 89 (`:46576-46580`); with
    /// extraUpdates 2 that is 3 sub-steps per update, so it dies on update 30.
    #[test]
    fn s1_p_i22_the_sparkle_guitar_note_arc_lifetime() {
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai_owned(SPARKLE_GUITAR, 0, 160.0, 160.0, 0.0, -20.0, 85, 1.5, 300.0, 160.0)
            .expect("the 856 row spawns");
        let mut w = world();
        for _ in 0..29 {
            step(&mut pool, &mut w);
        }
        assert!(pool.slots()[slot].active, "still alive at 87 sub-steps");
        step(&mut pool, &mut w);
        assert!(!pool.slots()[slot].active, "dies at localAI[0] >= 89");
    }

    /// The Charged Blaster Orb latches its scale to clamp(ai1, 0.7, 1.6) and
    /// resizes the box to 22·scale (`:54669-54673`); at scale ≥ 0.85 the
    /// penetrate flips to −1 (`:54680-54685`).
    #[test]
    fn s1_p_i22_the_charged_blaster_orb_scale_latch() {
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai_owned(CHARGED_BLASTER_ORB, 0, 160.0, 160.0, 10.0, 0.0, 100, 2.0, 0.0, 1.3)
            .expect("the 459 row spawns");
        let mut w = world();
        step(&mut pool, &mut w);
        let p = &pool.slots()[slot];
        assert_eq!(p.scale, 1.3, "ai1 clamped 0.7..1.6");
        assert_eq!((p.w, p.h), (28.0, 28.0), "22·1.3 = 28 (int trunc)");
        assert_eq!(p.penetrate, -1, "scale >= 0.85 flips penetrate");
    }

    /// The Heat Ray snapshots its start position at the delay tick 3
    /// (`AI_048_GetStartPositionSettingDelay` `:53990-53992`); with
    /// extraUpdates 100 the localAI[0] counter races, so the snapshot lands
    /// on the first update.
    #[test]
    fn s1_p_i22_the_heat_ray_snapshots_at_the_delay() {
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai_owned(HEAT_RAY, 0, 160.0, 160.0, 15.0, 0.0, 90, 3.0, 0.0, 0.0)
            .expect("the 260 row spawns");
        let mut w = world();
        step(&mut pool, &mut w);
        let p = &pool.slots()[slot];
        // The snapshot writes localAI[1]/[2] = the centre at the delay tick.
        assert!(p.local_ai[1] > 0.0, "the start X snapshot");
        assert!(p.local_ai[2] > 0.0, "the start Y snapshot");
        assert_eq!(p.alpha, 255, "the aiStyle-48 alpha write (`:28240`)");
    }
}

/// S1-P-i23 — the channel machinery witnesses (written, NOT run — code-only
/// mode): the cancel key's tracking (`NewProjectile`'s tail
/// `Projectile.cs:11097-11100` → `ChannelCancelKey.TryTracking`
/// `Player.cs:134-140`), the kill-cancel (`Kill`'s head `:70651-70659` →
/// `TryCancelChannel` `Player.cs:52975-52981`, `Matches` `:121-132`), the
/// `DontCancelChannelOnKill` exemption (`ProjectileID.cs:524`'s {190}) and
/// the out-of-world guard's no-`Kill()` deactivate (`Projectile.cs:16696`).
#[cfg(test)]
mod channel_machinery_tests {
    use super::*;

    fn world() -> World {
        World::new("t".into(), 64, 64)
    }

    /// One pool tick with the local player driving (the `step_player` shape
    /// of `magic_ai_tests` — no NPCs, the player's centre as the owner
    /// context, a fresh seeded stream per tick).
    fn tick(pool: &mut ProjectilePool, w: &mut World, p: &mut crate::player::Player) {
        let mut rng = tr_core::tile_light::FastRandom::new(7);
        let mut npcs: Vec<Npc> = Vec::new();
        let center = p.center();
        pool.update(
            w,
            &mut npcs,
            Some(center),
            None,
            Some(p),
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut rng,
            0,
            false,
        );
    }

    /// A mid-channel player on the Magic Missile row (item 113, shoot 16):
    /// the cancel key seeded as `StartChanneling(sItem)` does
    /// (`Player.cs:52963-52966` — type expected, index 0).
    fn missile_player(w: &World) -> crate::player::Player {
        let mut p = crate::player::Player::spawn(w);
        p.channel = true;
        p.channel_item = 113;
        p.channel_proj_expected = MAGIC_MISSILE;
        p.channel_index_expected = 0;
        p.channel_target = Vec2::new(500.0, 400.0);
        p
    }

    #[test]
    fn s1_p_i23_the_tracked_shots_death_drops_the_channel() {
        // `Kill`'s head (`Projectile.cs:70651-70659`): a dying local shot
        // whose type+index match the cancel key calls `TryCancelChannel`
        // (`Player.cs:52975-52981`) — `Matches` (`:127-130`) hits, the
        // channel drops. The tracked shot dies on its `timeLeft` tail
        // (`:17201-17204`'s `Kill()`).
        let mut w = world();
        let mut p = missile_player(&w);
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai(
                MAGIC_MISSILE, 300.0, 300.0, 0.0, 0.0, 30, 7.5, 500.0, 400.0,
            )
            .unwrap();
        // The use-path tail applies the spawn's tracking intent on the
        // spawn tick (`Projectile.cs:11097-11100`).
        pool.apply_channel_tracks(&mut p);
        assert_eq!(p.channel_index_expected, slot as u16, "the spawn tracked");
        // One tick to prove the hold stays open while the shot lives.
        tick(&mut pool, &mut w, &mut p);
        assert!(pool.slots()[slot].active);
        assert!(p.channel, "the live tracked shot keeps the channel");
        // The lifetime kill: the death hook runs the cancel. The held missile's
        // survival floor (`Projectile.cs:43336`, `timeLeft < 60 -> 60` while an
        // aim is present) would lift `time_left = 1` back to 60, so the fixture
        // releases the aim (`ai[0] = ai[1] = -1`) to let the lifetime tail kill;
        // the channel stays OPEN so the death-cancel hook is what drops it.
        pool.slots_mut()[slot].ai[0] = -1.0;
        pool.slots_mut()[slot].ai[1] = -1.0;
        pool.slots_mut()[slot].time_left = 1;
        tick(&mut pool, &mut w, &mut p);
        assert!(!pool.slots()[slot].active, "the lifetime tail kills");
        assert!(!p.channel, "the tracked shot's death cancels the channel");
    }

    #[test]
    fn s1_p_i23_an_untracked_shot_of_the_same_type_does_not_cancel() {
        // `Matches` (`Player.cs:127-130`) compares BOTH the type and the
        // index: a second Magic Missile in another slot is not the tracked
        // shot, so its death leaves the channel open.
        let mut w = world();
        let mut p = missile_player(&w);
        let mut pool = ProjectilePool::new();
        let tracked = pool
            .spawn_with_data_ai(
                MAGIC_MISSILE, 300.0, 300.0, 0.0, 0.0, 30, 7.5, 500.0, 400.0,
            )
            .unwrap();
        // The use-path tail tracks the first spawn; the second spawn's
        // intent is dropped (the test's extra shot, never applied).
        pool.apply_channel_tracks(&mut p);
        let other = pool
            .spawn_with_data_ai(
                MAGIC_MISSILE, 400.0, 300.0, 0.0, 0.0, 30, 7.5, 500.0, 400.0,
            )
            .unwrap();
        let _ = pool.drain_channel_tracks();
        assert_eq!(p.channel_index_expected, tracked as u16);
        assert_ne!(tracked, other);
        // Kill the untracked twin (release its aim so the survival floor
        // `Projectile.cs:43336` does not lift `time_left` back to 60).
        pool.slots_mut()[other].ai[0] = -1.0;
        pool.slots_mut()[other].ai[1] = -1.0;
        pool.slots_mut()[other].time_left = 1;
        tick(&mut pool, &mut w, &mut p);
        assert!(!pool.slots()[other].active, "the twin died");
        assert!(pool.slots()[tracked].active);
        assert!(p.channel, "the untracked twin's death does not cancel");
    }

    #[test]
    fn s1_p_i23_the_last_spawn_of_the_expected_type_wins() {
        // `ChannelCancelKey.TryTracking` (`Player.cs:134-140`): every spawn
        // of the expected type overwrites the index — two Magic Missiles
        // in one tick, the second is the tracked one, and the FIRST's death
        // no longer cancels while the second's does.
        let mut w = world();
        let mut p = missile_player(&w);
        let mut pool = ProjectilePool::new();
        let first = pool
            .spawn_with_data_ai(
                MAGIC_MISSILE, 300.0, 300.0, 0.0, 0.0, 30, 7.5, 500.0, 400.0,
            )
            .unwrap();
        let second = pool
            .spawn_with_data_ai(
                MAGIC_MISSILE, 400.0, 300.0, 0.0, 0.0, 30, 7.5, 500.0, 400.0,
            )
            .unwrap();
        pool.apply_channel_tracks(&mut p);
        assert_eq!(
            p.channel_index_expected, second as u16,
            "the last spawn of the expected type wins"
        );
        pool.slots_mut()[first].ai[0] = -1.0;
        pool.slots_mut()[first].ai[1] = -1.0;
        pool.slots_mut()[first].time_left = 1;
        tick(&mut pool, &mut w, &mut p);
        assert!(!pool.slots()[first].active);
        assert!(p.channel, "the superseded shot's death does not cancel");
        pool.slots_mut()[second].ai[0] = -1.0;
        pool.slots_mut()[second].ai[1] = -1.0;
        pool.slots_mut()[second].time_left = 1;
        tick(&mut pool, &mut w, &mut p);
        assert!(!pool.slots()[second].active);
        assert!(!p.channel, "the tracked (last) shot's death cancels");
    }

    #[test]
    fn s1_p_i23_a_foreign_owners_death_never_cancels() {
        // `Kill`'s owner gate (`Projectile.cs:70656`'s `owner ==
        // Main.myPlayer`): a peer's shot dying in slot 0 with the local
        // key's type+index still matches nothing — the cancel is local-only.
        // The peer's slot simulates under its own `local_owner` (the wire
        // pass shape), so the lifetime kill runs.
        let mut w = world();
        let mut p = missile_player(&w);
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai_owned(
                MAGIC_MISSILE, 1, 300.0, 300.0, 0.0, 0.0, 30, 7.5, 500.0, 400.0,
            )
            .unwrap();
        pool.slots_mut()[slot].ai[0] = -1.0;
        pool.slots_mut()[slot].ai[1] = -1.0;
        pool.slots_mut()[slot].time_left = 1;
        let mut rng = tr_core::tile_light::FastRandom::new(7);
        let mut npcs: Vec<Npc> = Vec::new();
        pool.update(
            &mut w,
            &mut npcs,
            None,
            None,
            Some(&mut p),
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut rng,
            1, // the peer's machine: its own shots simulate
            false,
        );
        assert!(!pool.slots()[slot].active, "the peer's shot died");
        assert!(p.channel, "a foreign owner's death never cancels");
    }

    #[test]
    fn s1_p_i23_the_piranhas_death_is_exempt() {
        // `DontCancelChannelOnKill` (`ProjectileID.cs:524`'s {190}): the
        // Piranha Gun's piranha dies without cancelling — `Kill`'s `flag`
        // (`Projectile.cs:70651-70655`) is false for the type, so the
        // `TryCancelChannel` call never runs even on a type+index match.
        // The 190 row is unported (`proj_data` None — the slot rides the
        // raw spawn, the Piranha Gun's own AI task), so the lifetime tail
        // is the kill path.
        let mut w = world();
        let mut p = crate::player::Player::spawn(&w);
        p.channel = true;
        p.channel_item = 1156; // the Piranha Gun, shoot 190
        p.channel_proj_expected = 190;
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn(190, 0, Vec2::new(300.0, 300.0), Vec2::ZERO, 40, 1.0, false)
            .unwrap();
        pool.apply_channel_tracks(&mut p);
        assert_eq!(p.channel_index_expected, slot as u16, "the raw spawn tracks too");
        pool.slots_mut()[slot].time_left = 1;
        tick(&mut pool, &mut w, &mut p);
        assert!(!pool.slots()[slot].active, "the piranha died");
        assert!(p.channel, "the 190 exemption keeps the channel");
    }

    #[test]
    fn s1_p_i23_the_magic_string_ghost_cancels_without_a_key_match() {
        // `Matches`'s first arm (`Player.cs:123-126`): an aiStyle-99 slot
        // with `ai[0] == -3` (the Magic String's ghost,
        // `Projectile.cs:68023-68025`) cancels regardless of the key — the
        // key here expects a DIFFERENT type and index. The ghost's NaN
        // velocity kill (`:67853-67855`'s `Kill()`) rides the death hook.
        let mut w = world();
        let mut p = missile_player(&w); // expects 16, index 0 — not the yoyo
        let mut pool = ProjectilePool::new();
        let ghost = pool
            .spawn_with_data_ai(WOOD_YOYO, 400.0, 400.0, 0.0, 0.0, 9, 2.5, -3.0, 0.0)
            .unwrap();
        // The key's type (16) never matches the yoyo's 541 — the cancel
        // can only come from the ghost arm.
        assert_eq!(p.channel_proj_expected, MAGIC_MISSILE);
        pool.slots_mut()[ghost].vel.x = f32::NAN;
        tick(&mut pool, &mut w, &mut p);
        assert!(!pool.slots()[ghost].active, "the NaN kill ran");
        assert!(!p.channel, "the aiStyle-99 −3 ghost cancels on its own");
    }

    #[test]
    fn s1_p_i23_a_live_yoyo_death_without_the_ghost_state_does_not_cancel() {
        // The ghost arm is strict: `ai[0] == -3` only. A returning yoyo
        // (`ai[0] == -1`, no Magic String) dying on the owner-death gate
        // (`:67824-67827`'s `Kill()`) matches neither arm — the key expects
        // 16, and −1 is not −3.
        let mut w = world();
        let mut p = missile_player(&w);
        let mut pool = ProjectilePool::new();
        let yoyo = pool
            .spawn_with_data_ai(WOOD_YOYO, 400.0, 400.0, 0.0, 0.0, 9, 2.5, -1.0, 0.0)
            .unwrap();
        pool.slots_mut()[yoyo].vel.x = f32::NAN;
        tick(&mut pool, &mut w, &mut p);
        assert!(!pool.slots()[yoyo].active, "the NaN kill ran");
        assert!(p.channel, "−1 is not the ghost state — no cancel");
    }

    #[test]
    fn s1_p_i23_the_out_of_world_deactivate_never_cancels() {
        // `Projectile.Update`'s out-of-world guard (`Projectile.cs:16684-
        // 16698`): `active = false` + `return` — NO `Kill()` call, so the
        // channel-cancel head never runs. The tracked shot leaves the
        // world; the channel stays open (the C# behaviour — the latch
        // drops only on the release/CC/death paths).
        let mut w = world();
        let mut p = missile_player(&w);
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai(
                MAGIC_MISSILE, -40.0, 300.0, 0.0, 0.0, 30, 7.5, 500.0, 400.0,
            )
            .unwrap();
        pool.apply_channel_tracks(&mut p);
        assert_eq!(p.channel_index_expected, slot as u16);
        tick(&mut pool, &mut w, &mut p);
        assert!(!pool.slots()[slot].active, "the guard deactivated the slot");
        assert!(p.channel, "the guard's deactivate is not a Kill()");
    }

    #[test]
    fn s1_p_i23_the_untracked_cache_matches_slot_zero_verbatim() {
        // `StartChanneling(Item)` news the key with ONLY the type set
        // (`Player.cs:52963-52966`) — `ProjectileIndexExpected` keeps the
        // struct's 0 default. A slot-0 shot of the expected type dying
        // BEFORE any tracking intent applied still matches (`:127-130`):
        // the port keeps the 0 default, not an Option.
        let mut w = world();
        let mut p = missile_player(&w);
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai(
                MAGIC_MISSILE, 300.0, 300.0, 0.0, 0.0, 30, 7.5, 500.0, 400.0,
            )
            .unwrap();
        assert_eq!(slot, 0);
        assert_eq!(p.channel_index_expected, 0, "the struct default");
        // NO apply_channel_tracks — the raw 0 default is the match. Release the
        // aim so the survival floor (`Projectile.cs:43336`) does not lift
        // `time_left` back to 60.
        pool.slots_mut()[slot].ai[0] = -1.0;
        pool.slots_mut()[slot].ai[1] = -1.0;
        pool.slots_mut()[slot].time_left = 1;
        tick(&mut pool, &mut w, &mut p);
        assert!(!pool.slots()[slot].active);
        assert!(!p.channel, "the untracked 0 default matches slot 0");
    }
}

#[cfg(test)]
mod s1_p_i56_guardian_tests {
    //! S1-P-i56 — the Stardust Guardian arm (`AI_120_StardustGuardian`,
    //! `Projectile.cs:44634-44963` + `AI_120_StardustGuardian_FindTarget`
    //! `:44965-44982`, the dispatch `:34888-34891`). WRITTEN NOT RUN
    //! (code-only mode). The witnesses mirror the C# state machine on the
    //! port's seams: the idle drift + leash-gated acquire, the attack
    //! posture's accel/damp pairs, the owner-only dash commit, the dash's
    //! double MoveTowards steering + 4-tick retarget, the abort gates, the
    //! rest-hover/teleport states (the rest point stays ZERO until the
    //! Forbidden set writer lands — the revert arms are the live path),
    //! the tank-pet claim + the player-side decay, and the ZERO-draw RNG
    //! census (every roll in the C# arm is a NewDust internal).
    use super::*;
    use crate::npc::{Npc, NpcKind};
    use crate::player::Player;

    fn world() -> World {
        World::new("t".into(), 256, 128)
    }

    /// The owner at a fixed spot: centre (410, 321) — x 400 + WIDTH/2,
    /// y 300 + height/2 (42). Facing 1 (the spawn default).
    fn owner(w: &World) -> Player {
        let mut p = Player::spawn(w);
        p.x = 400.0;
        p.y = 300.0;
        p.stardust_guardian = true;
        p.max_minions = 1;
        p
    }

    /// A Guardian slot placed by CENTRE (the C# witnesses reason in
    /// centres; the spawn seam takes the position corner).
    fn guardian_at(w: &World, cx: f32, cy: f32) -> Projectile {
        let d = proj_data(STARDUST_GUARDIAN).unwrap();
        Projectile {
            active: true,
            kind: STARDUST_GUARDIAN,
            owner: 0,
            pos: Vec2::new(cx - d.w * 0.5, cy - d.h * 0.5),
            w: d.w,
            h: d.h,
            time_left: d.time_left,
            max_penetrate: d.penetrate,
            penetrate: d.penetrate,
            uses_local_immunity: d.uses_local_immunity,
            local_hit_cooldown: d.local_hit_cooldown,
            tile_collide: d.tile_collide,
            minion: d.minion,
            minion_slots: d.minion_slots,
            net_important: d.net_important,
            ignore_water: d.ignore_water,
            ..Default::default()
        }
    }

    /// A chaseable NPC by CENTRE — the Zombie's 18x40 box
    /// (`npc/data.rs:2522-2543`).
    fn npc_centered(cx: f32, cy: f32) -> Npc {
        let mut n = Npc::new(NpcKind::Zombie, 0.0, 0.0, 1, 0.0);
        n.max_hp = 40;
        n.hp = 40;
        let (w, h) = n.size();
        n.x = cx - w * 0.5;
        n.y = cy - h * 0.5;
        n
    }

    /// One AI tick on the bare slot (no pool bookkeeping) — the arm under
    /// test, `whoAmI` 7 (a non-zero slot so the tank claim is observable).
    fn ai_tick(p: &mut Projectile, pl: &mut Player, npcs: &[Npc]) {
        p.ai_stardust_guardian(7, Some(pl), npcs, 0);
    }

    /// The scripted stream: records every draw (the `DebrisScript` shape).
    /// The Guardian arm must draw NOTHING through the whole pool pass.
    struct CensusRng {
        draws: Vec<(i32, i32)>,
        floats: usize,
    }
    impl tr_core::loot::DropRng for CensusRng {
        fn next_range(&mut self, min: i32, max: i32) -> i32 {
            self.draws.push((min, max));
            max - 1
        }
        fn next_float(&mut self) -> f32 {
            self.floats += 1;
            0.5
        }
    }

    /// The row + sheet pins: the SetDefaults slice (`Projectile.cs:6699-
    /// 6716`) and the 19-frame sheet (`Main.cs:8497`).
    #[test]
    fn s1_p_i56_the_row_and_sheet_match_set_defaults() {
        let d = proj_data(STARDUST_GUARDIAN).unwrap();
        assert_eq!((d.w, d.h), (50.0, 80.0), ":6702-6703");
        assert_eq!(d.ai_style, 120, ":6704");
        assert_eq!(d.penetrate, -1, ":6705");
        assert_eq!(d.time_left, 18000, ":6706 — the *= 5 off 3600 (:787)");
        assert!(d.minion && !d.sentry, ":6707");
        assert_eq!(d.minion_slots, 0.0, ":6709 — the 0-slot pet");
        assert!(d.ignore_water, ":6710");
        assert!(!d.tile_collide, ":6711");
        assert!(d.net_important, ":6701/:6712");
        assert!(d.uses_local_immunity, ":6714");
        assert_eq!(d.local_hit_cooldown, 5, ":6715");
        assert_eq!(proj_frames(STARDUST_GUARDIAN), 19, "Main.cs:8497");
    }

    /// The owner-inactive kill (`:44636-44641`): no player → dead slot,
    /// nothing else touched.
    #[test]
    fn s1_p_i56_the_inactive_owner_kills_the_guardian() {
        let w = world();
        let mut p = guardian_at(&w, 410.0, 321.0);
        p.ai_stardust_guardian(7, None, &[], 0);
        assert!(!p.active, ":44639");
        assert_eq!(p.time_left, 0, "the port's death convention (kill())");
    }

    /// The idle drift (`:44687-44697`): the 5% centre lerp toward the
    /// hover point (owner centre − (15·facing, 25)), the velocity halves,
    /// the facing rides the owner, the 9-tick frame machine wraps at 8.
    #[test]
    fn s1_p_i56_the_idle_drifts_to_the_hover_point() {
        let w = world();
        let mut pl = owner(&w);
        // Centre (500, 400): the hover point is (395, 296) — 410−15, 321−25.
        let mut p = guardian_at(&w, 500.0, 400.0);
        p.vel = Vec2::new(4.0, -2.0);
        p.alpha = 255; // the materialize flash arms
        ai_tick(&mut p, &mut pl, &[]);
        // Lerp((500,400), (395,296), 0.05) = (494.75, 394.8).
        let c = Vec2::from(p.center());
        assert!((c.x - 494.75).abs() < 1e-3, "the 5% x lerp: {}", c.x);
        assert!((c.y - 394.8).abs() < 1e-3, "the 5% y lerp: {}", c.y);
        assert_eq!(p.vel, Vec2::new(2.0, -1.0), ":44688 — the halves");
        assert_eq!(p.direction, 1, ":44689 — the owner's facing");
        assert_eq!(p.sprite_direction, 1);
        assert_eq!(p.alpha, 0, ":44663-44665 — the materialize flash");
        assert_eq!(p.frame_counter, 1, ":44690 — the first tick");
        // The keep-alive pin (`:44655-44658`): the live flag pins 2.
        assert_eq!(p.time_left, 2, ":44657");
        // Eight more ticks: the counter wraps on the 9th, the frame steps.
        for _ in 0..8 {
            ai_tick(&mut p, &mut pl, &[]);
        }
        assert_eq!(p.frame_counter, 0, ":44691-44692 — the 9-tick wrap");
        assert_eq!(p.frame, 1, ":44693");
        // The idle state claims NO tank pet (`:44680`).
        assert_eq!(pl.tank_pet, -1);
    }

    /// The dead owner clears the summon flag (`:44651-44654`) — no pin,
    /// the life runs down.
    #[test]
    fn s1_p_i56_the_dead_owner_clears_the_flag() {
        let w = world();
        let mut pl = owner(&w);
        pl.dead = true;
        let mut p = guardian_at(&w, 410.0, 321.0);
        let tl = p.time_left;
        ai_tick(&mut p, &mut pl, &[]);
        assert!(!pl.stardust_guardian, ":44653");
        assert_eq!(p.time_left, tl, "no pin on the dead owner");
        assert!(p.active, "the slot lives until the life runs out");
    }

    /// The acquire scan (`:44698-44708` + `:44965-44982`): the nearest
    /// chaseable NPC to the OWNER's centre inside 500 px; the posture
    /// faces it, the X accel fires inside the leash band, and the
    /// owner-only commit arms the dash (`:44734-44739`).
    #[test]
    fn s1_p_i56_the_idle_acquire_commits_the_dash() {
        let w = world();
        let mut pl = owner(&w);
        // Guardian at the hover point (395, 296) — inside the leash, so
        // the scan runs. NPC centre (475, 300): 65 px off the owner
        // (inside 500), 80 px right of the Guardian.
        let mut p = guardian_at(&w, 395.0, 296.0);
        let npcs = vec![npc_centered(475.0, 300.0)];
        ai_tick(&mut p, &mut pl, &npcs);
        assert_eq!(p.ai[0], 2.0, ":44736 — the dash commit");
        assert_eq!(p.ai[1], 0.0, ":44737 — the target index");
        assert!(p.net_update, ":44738");
        assert_eq!(p.direction, 1, ":44712 — face the target");
        // The X accel (`:44718-44721`): num6 = |395−395| = 0 < 150,
        // num7 = 80 ∈ (20, 250) → vx += 0.1 (the idle half ran first:
        // 0 × 0.5 = 0). The lerp moved the centre 5% toward (395,296) —
        // it was already there, so the distances hold exactly.
        assert!((p.vel.x - 0.1).abs() < 1e-5, "the 0.1 accel: {}", p.vel.x);
    }

    /// The scan is the OWNER-centred nearest pick (`:44967-44979`), NOT
    /// the Guardian's: a far-from-owner NPC inside the Guardian's own
    /// reach is skipped; the closer-to-owner one wins even when farther
    /// from the Guardian. The range shrinks per pick.
    #[test]
    fn s1_p_i56_the_scan_centres_on_the_owner() {
        let npcs = vec![
            npc_centered(1000.0, 321.0), // 590 off the owner — outside 500
            npc_centered(700.0, 321.0),  // 290 off the owner
            npc_centered(600.0, 321.0),  // 190 off the owner — the pick
        ];
        let (t, d) = Projectile::ai_120_guardian_find_target(
            &npcs,
            Vec2::new(410.0, 321.0),
            500.0,
            500.0,
        );
        assert_eq!(t, 2, "the nearest to the OWNER");
        assert!((d - 190.0).abs() < 1e-3, "the returned distance: {d}");
        // No chaseable NPC inside the range: −1, the seed passes through.
        let dead = vec![{
            let mut n = npc_centered(500.0, 321.0);
            n.hp = 0;
            n
        }];
        let (t, d) = Projectile::ai_120_guardian_find_target(
            &dead,
            Vec2::new(410.0, 321.0),
            500.0,
            -1.0,
        );
        assert_eq!(t, -1);
        assert_eq!(d, -1.0, "the −1 seed of the dash retarget (:44895)");
    }

    /// The leash gate (`:44701-44704`): more than num + 20 = 170 px off
    /// the hover point in X, the scan never runs — no dash commit even
    /// with a target in range.
    #[test]
    fn s1_p_i56_the_far_guardian_skips_the_scan() {
        let w = world();
        let mut pl = owner(&w);
        // Centre (600, 296): |600 − 395| = 205 > 170 → flag3 false.
        let mut p = guardian_at(&w, 600.0, 296.0);
        let npcs = vec![npc_centered(475.0, 300.0)];
        ai_tick(&mut p, &mut pl, &npcs);
        assert_eq!(p.ai[0], 0.0, "the scan was gated off");
        assert!(!p.net_update);
    }

    /// The non-local owner never commits the dash (`:44734` — the
    /// `owner == Main.myPlayer` gate); the posture still runs.
    #[test]
    fn s1_p_i56_the_foreign_owner_never_commits() {
        let w = world();
        let mut pl = owner(&w);
        let mut p = guardian_at(&w, 395.0, 296.0);
        p.owner = 3; // not the local player 0
        let npcs = vec![npc_centered(475.0, 300.0)];
        ai_tick(&mut p, &mut pl, &npcs);
        assert_eq!(p.ai[0], 0.0, "no commit off-machine");
        assert_eq!(p.direction, 1, "the posture still faces the target");
        assert!((p.vel.x - 0.1).abs() < 1e-5, "the accel still runs");
    }

    /// The dash steering (`:44885-44890`): the stand-off point on the
    /// target's far side from the owner, the 6·Remap(len, 50, 400, 1, 4)
    /// cap, the double MoveTowards (aim capped, then the 32-px velocity
    /// step). Hand-computed: owner (410,321), Guardian (410,321), NPC
    /// centre (610,321) → num18 = 1, the Zombie's 18-px box gives the
    /// offset (−(9+70), −10) = (−79,−10), target_position = (121,−10);
    /// from rest the velocity IS the capped aim (len < 32).
    #[test]
    fn s1_p_i56_the_dash_steers_to_the_standoff_point() {
        let w = world();
        let mut pl = owner(&w);
        let mut p = guardian_at(&w, 410.0, 321.0);
        p.ai[0] = 2.0;
        p.ai[1] = 0.0;
        let npcs = vec![npc_centered(610.0, 321.0)];
        ai_tick(&mut p, &mut pl, &npcs);
        assert_eq!(p.ai[0], 2.0, "the dash holds");
        assert_eq!(p.direction, 1, ":44890 — num18");
        assert_eq!(p.sprite_direction, 1);
        // The C# float chain, mirrored: len = sqrt(121² + 10²).
        let len = (121.0f32 * 121.0 + 10.0 * 10.0).sqrt();
        let ramp = get_lerp_value(50.0, 400.0, len);
        let cap = 6.0 * (1.0 + 3.0 * ramp);
        let aim = Vec2::new(121.0, -10.0).normalize() * cap;
        assert!((p.vel.x - aim.x).abs() < 1e-3, "vx {}: want {}", p.vel.x, aim.x);
        assert!((p.vel.y - aim.y).abs() < 1e-3, "vy {}: want {}", p.vel.y, aim.y);
        // The tank claim (`:44680-44684`): the non-idle tick pins it.
        assert_eq!(pl.tank_pet, 7, "the whoAmI stamp");
        assert!(!pl.tank_pet_reset, "the decay disarm");
        // The retarget counter (`:44891`): the post-increment fires at
        // the OLD value 3 — tick 1 reads 0, so localAI[0] is now 1.
        assert_eq!(p.local_ai[0], 1.0);
    }

    /// The 4-tick retarget (`:44891-44902`): ticks 1-3 advance the
    /// counter, tick 4 (old value 3) resets it and re-scans; a found
    /// target rewrites ai[1] + netUpdate.
    #[test]
    fn s1_p_i56_the_dash_retargets_every_fourth_tick() {
        let w = world();
        let mut pl = owner(&w);
        let mut p = guardian_at(&w, 410.0, 321.0);
        p.ai[0] = 2.0;
        p.ai[1] = 0.0;
        // Target 0 close (holds the dash), target 1 nearer the OWNER —
        // the retarget must flip to it on tick 4.
        let npcs = vec![
            npc_centered(610.0, 321.0), // 200 off the owner
            npc_centered(510.0, 321.0), // 100 off the owner
        ];
        for _ in 0..3 {
            ai_tick(&mut p, &mut pl, &npcs);
            assert_eq!(p.ai[1], 0.0, "no retarget before tick 4");
        }
        assert_eq!(p.local_ai[0], 3.0);
        p.net_update = false;
        ai_tick(&mut p, &mut pl, &npcs);
        assert_eq!(p.local_ai[0], 0.0, ":44893 — the reset");
        assert_eq!(p.ai[1], 1.0, ":44899 — the nearer pick");
        assert!(p.net_update, ":44900");
    }

    /// The abort gates (`:44858-44882`): the Guardian beyond 500 px of
    /// the OWNER, or the target unchaseable / beyond 500 px of the
    /// Guardian, reverts to idle with ai[1] cleared and the frame floored
    /// at 18.
    #[test]
    fn s1_p_i56_the_dash_aborts_on_the_two_gates() {
        let w = world();
        let mut pl = owner(&w);
        // Gate 1: the Guardian itself out of the owner's 500-px reach.
        let mut p = guardian_at(&w, 1010.0, 321.0); // 600 off the owner
        p.ai[0] = 2.0;
        p.ai[1] = 0.0;
        p.frame = 5;
        let npcs = vec![npc_centered(1010.0, 321.0)];
        ai_tick(&mut p, &mut pl, &npcs);
        assert_eq!(p.ai[0], 0.0, ":44876 — flag5 false");
        assert_eq!(p.ai[1], 0.0, ":44875");
        assert!(p.net_update);
        assert_eq!(p.frame, 18, ":44878-44881 — the recover floor");
        // Gate 2: the target dead (unchaseable) while the Guardian is home.
        let mut p = guardian_at(&w, 410.0, 321.0);
        p.ai[0] = 2.0;
        p.ai[1] = 0.0;
        p.frame = 20; // above the floor — the max(18, frame) keeps it
        let mut dead = npc_centered(500.0, 321.0);
        dead.hp = 0;
        ai_tick(&mut p, &mut pl, &[dead]);
        assert_eq!(p.ai[0], 0.0, ":44868 — CanBeChasedBy false");
        assert_eq!(p.frame, 20, "the floor only lifts");
        // Gate 2b: the target beyond the Guardian's 500-px reach while
        // the Guardian stays inside the owner's (gate 1 holds at 490 px;
        // the target 550 px off the Guardian — the dash's held ai[1]
        // never re-checks the owner side).
        let mut p = guardian_at(&w, 900.0, 321.0); // 490 off the owner — gate 1 holds
        p.ai[0] = 2.0;
        p.ai[1] = 0.0;
        let npcs = vec![npc_centered(350.0, 321.0)]; // 550 off the Guardian
        ai_tick(&mut p, &mut pl, &npcs);
        assert_eq!(p.ai[0], 0.0, ":44868 — the distance gate");
        // The out-of-range index (`IndexInRange`, :44865): ai[1] = 99
        // with one NPC — no panic, the abort fires.
        let mut p = guardian_at(&w, 410.0, 321.0);
        p.ai[0] = 2.0;
        p.ai[1] = 99.0;
        ai_tick(&mut p, &mut pl, &[npc_centered(500.0, 321.0)]);
        assert_eq!(p.ai[0], 0.0);
    }

    /// The dash frame machine (`:44838-44857`): the floor at 12, the
    /// 8-tick rate on frames 12/13 (3 otherwise), the wrap 19 → 14. The
    /// target sits 100 px off the owner so the flying Guardian stays
    /// inside both 500-px gates for the whole 39-tick walk.
    #[test]
    fn s1_p_i56_the_dash_frame_machine() {
        let w = world();
        let mut pl = owner(&w);
        let mut p = guardian_at(&w, 410.0, 321.0);
        p.ai[0] = 2.0;
        p.ai[1] = 0.0;
        p.frame = 3; // below the floor
        let npcs = vec![npc_centered(510.0, 321.0)];
        ai_tick(&mut p, &mut pl, &npcs);
        assert_eq!(p.frame, 12, ":44841-44844 — the floor");
        assert_eq!(p.frame_counter, 1);
        // 7 more ticks at rate 8: the counter wraps on the 8th, 12 → 13.
        for _ in 0..7 {
            ai_tick(&mut p, &mut pl, &npcs);
        }
        assert_eq!(p.frame, 13);
        assert_eq!(p.frame_counter, 0);
        // 8 more: 13 → 14, then the rate drops to 3.
        for _ in 0..8 {
            ai_tick(&mut p, &mut pl, &npcs);
        }
        assert_eq!(p.frame, 14);
        for _ in 0..3 {
            ai_tick(&mut p, &mut pl, &npcs);
        }
        assert_eq!(p.frame, 15, "the 3-tick rate past frame 13");
        // Walk to the wrap: frames 15 → 16 → 17 → 18 at 3 ticks each,
        // then 18 → 19 wraps to 14 (`:44852-44855`) — 12 ticks, 4 wraps.
        for _ in 0..12 {
            ai_tick(&mut p, &mut pl, &npcs);
        }
        assert_eq!(p.frame, 14, ":44854 — the 19 → 14 wrap");
    }

    /// The rest-hover revert (`:44744-44752`): no rest point → ai[0] 0 +
    /// netUpdate, but the C# CONTINUES into the scan/drift block with the
    /// hover point (no early return) — near the hover point the drift
    /// damps 0.8 and the state stays 0 (the teleport tail does not run).
    #[test]
    fn s1_p_i56_the_rest_state_reverts_without_a_point() {
        let w = world();
        let mut pl = owner(&w);
        // Centre (400, 300): the hover point (395, 296) is 5/4 px off —
        // inside both dead-bands, so the drift damps and nothing re-arms.
        let mut p = guardian_at(&w, 400.0, 300.0);
        p.ai[0] = 1.0;
        p.vel = Vec2::new(3.0, 3.0);
        ai_tick(&mut p, &mut pl, &[]);
        assert_eq!(p.ai[0], 0.0, ":44750");
        assert!(p.net_update, ":44751");
        assert_eq!(p.vel, Vec2::new(2.4, 2.4), ":44810/:44824 — the 0.8 damp");
        // The tank claim ran BEFORE the revert (ai[0] was 1, :44680).
        assert_eq!(pl.tank_pet, 7);
    }

    /// The rest drift (`:44798-44825`) with a rest point: inside the
    /// ±20/±10 dead-bands the velocity damps 0.8 and the X facing reads
    /// the OWNER's centre; outside, the 0.06 accel toward the point.
    #[test]
    fn s1_p_i56_the_rest_drift_damps_and_steers() {
        let w = world();
        let mut pl = owner(&w);
        pl.minion_rest_target_point = Vec2::new(400.0, 316.0);
        // Guardian centre (410, 321): dx = −10 (inside 20), dy = −5
        // (inside 10) → both damp; the facing reads the owner centre
        // 410 < 410 false → −1 (`:44811`, ToDirectionInt).
        let mut p = guardian_at(&w, 410.0, 321.0);
        p.ai[0] = 1.0;
        p.vel = Vec2::new(2.0, 2.0);
        ai_tick(&mut p, &mut pl, &[]);
        assert_eq!(p.vel, Vec2::new(1.6, 1.6), "the 0.8 damp pair");
        assert_eq!(p.direction, -1, ":44811 — the owner-relative facing");
        assert_eq!(p.ai[0], 1.0, "the hover holds");
        // Outside the X band: centre (450, 321), dx = −50 → face left,
        // vx += −0.06. dy = −5 stays damped.
        let mut p = guardian_at(&w, 450.0, 321.0);
        p.ai[0] = 1.0;
        ai_tick(&mut p, &mut pl, &[]);
        assert_eq!(p.direction, -1, ":44805");
        assert!((p.vel.x + 0.06).abs() < 1e-6, "the 0.06 accel");
        assert_eq!(p.vel.y, 0.0);
        // Beyond num + 40 = 190 px in X: the teleport state arms and the
        // tail runs THIS tick (alpha flip + the 0.7 damp + the 20% lerp).
        let mut p = guardian_at(&w, 650.0, 321.0); // dx = −250
        p.ai[0] = 1.0;
        p.vel = Vec2::new(10.0, 0.0);
        p.alpha = 0;
        ai_tick(&mut p, &mut pl, &[]);
        assert_eq!(p.ai[0], 3.0, ":44800 — the teleport arm");
        assert_eq!(p.alpha, 255, ":44923-44925 — the dematerialize flash");
        assert!((p.vel.x - 7.0).abs() < 1e-4, ":44956 — the 0.7 damp");
        // Lerp((650,321), (400,316), 0.2) = (600, 320).
        let c = Vec2::from(p.center());
        assert!((c.x - 600.0).abs() < 1e-3, "the 20% lerp: {}", c.x);
        assert!((c.y - 320.0).abs() < 1e-3);
    }

    /// The teleport arrival (`:44958-44962`): inside 10 px of the rest
    /// point the state flips to the hover (1) + netUpdate. Without a
    /// rest point the state reverts to idle but the lerp still runs
    /// (`:44918-44922` — no early return).
    #[test]
    fn s1_p_i56_the_teleport_arrives_and_reverts() {
        let w = world();
        let mut pl = owner(&w);
        pl.minion_rest_target_point = Vec2::new(400.0, 316.0);
        // Centre (405, 318): after the 20% lerp → (404, 317.6), 4.03 px
        // off the point — inside 10.
        let mut p = guardian_at(&w, 405.0, 318.0);
        p.ai[0] = 3.0;
        ai_tick(&mut p, &mut pl, &[]);
        assert_eq!(p.ai[0], 1.0, ":44960 — the arrival");
        assert!(p.net_update);
        // No rest point: revert to 0, the lerp toward the HOVER point
        // (395, 296) still runs this tick.
        pl.minion_rest_target_point = Vec2::ZERO;
        let mut p = guardian_at(&w, 500.0, 400.0);
        p.ai[0] = 3.0;
        p.vel = Vec2::new(2.0, 0.0);
        ai_tick(&mut p, &mut pl, &[]);
        assert_eq!(p.ai[0], 0.0, ":44920");
        assert!(p.net_update);
        let c = Vec2::from(p.center());
        // Lerp((500,400), (395,296), 0.2) = (479, 379.2).
        assert!((c.x - 479.0).abs() < 1e-3, "the revert-tick lerp: {}", c.x);
        assert!((c.y - 379.2).abs() < 1e-3);
        assert!((p.vel.x - 1.4).abs() < 1e-5, "the 0.7 damp");
    }

    /// The tank-pet decay (`Player.cs:24539-24548`): the first tick arms
    /// the grace latch, the second drops an un-re-pinned claim; a live
    /// Guardian's re-pin (the AI's `tankPetReset = false`) keeps it.
    #[test]
    fn s1_p_i56_the_tank_pet_decay_and_repin() {
        let w = world();
        let mut pl = owner(&w);
        pl.tank_pet = 7;
        pl.tank_pet_decay();
        assert_eq!(pl.tank_pet, 7, "the grace tick keeps the claim");
        assert!(pl.tank_pet_reset);
        pl.tank_pet_decay();
        assert_eq!(pl.tank_pet, -1, ":24547 — the second tick drops it");
        // The re-pin cycle: claim → decay arms → the AI disarms → the
        // decay arms again — the claim never drops while the dash runs.
        pl.tank_pet = 7;
        pl.tank_pet_reset = false;
        let mut p = guardian_at(&w, 410.0, 321.0);
        p.ai[0] = 2.0;
        p.ai[1] = 0.0;
        let npcs = vec![npc_centered(610.0, 321.0)];
        for _ in 0..4 {
            pl.tank_pet_decay();
            ai_tick(&mut p, &mut pl, &npcs);
            assert_eq!(pl.tank_pet, 7, "the live dash keeps its claim");
            assert!(!pl.tank_pet_reset, "the AI re-disarms (:44683)");
        }
        // The idle state does NOT re-pin — two decays drop the claim.
        p.ai[0] = 0.0;
        pl.tank_pet_decay();
        ai_tick(&mut p, &mut pl, &npcs);
        pl.tank_pet_decay();
        assert_eq!(pl.tank_pet, -1, "the idle Guardian lets it go");
    }

    /// The rest-point invalidation (`Player.cs:57005-57007`): a point
    /// beyond 1000 px of the player's CENTRE zeroes; inside stays.
    #[test]
    fn s1_p_i56_the_far_rest_point_zeroes() {
        let w = world();
        let mut pl = owner(&w); // centre (410, 321)
        pl.minion_rest_target_point = Vec2::new(1411.0, 321.0); // 1001 px
        pl.invalidate_minion_target(&[]);
        assert_eq!(pl.minion_rest_target_point, Vec2::ZERO, ">1000 drops");
        pl.minion_rest_target_point = Vec2::new(1409.0, 321.0); // 999 px
        pl.invalidate_minion_target(&[]);
        assert_eq!(
            pl.minion_rest_target_point,
            Vec2::new(1409.0, 321.0),
            "inside 1000 stays"
        );
    }

    /// The dispatch wiring + the ZERO-draw RNG census: a pool-spawned
    /// Guardian runs the arm (the idle drift moves it off the spawn
    /// corner), the keep-alive pins the life, and the WHOLE pass draws
    /// nothing on the UpdateProjectiles stream — every C# roll in the
    /// arm is a NewDust internal (`:44668`/`:44672`/`:44928`/`:44932`/
    /// `:44943`/`:44948`), the documented dust-pool skip.
    #[test]
    fn s1_p_i56_the_dispatch_runs_and_draws_nothing() {
        let mut pool = ProjectilePool::new();
        let mut w = world();
        let mut pl = owner(&w);
        let slot = pool
            .spawn_with_data_ai_owned(
                STARDUST_GUARDIAN,
                0,
                475.0, // centre (500, 360) — off the hover point
                320.0,
                0.0,
                0.0,
                10,
                1.0,
                0.0,
                0.0,
            )
            .unwrap();
        let mut rng = CensusRng { draws: Vec::new(), floats: 0 };
        for _ in 0..12 {
            pl.num_minions = 0;
            pl.slots_minions = 0.0;
            pool.update(
                &mut w,
                &mut [],
                None,
                None,
                Some(&mut pl),
                YoyoInputs::default(),
                FlailInputs::default(),
                &mut rng,
                0,
                true,
            );
        }
        let p = &pool.slots()[slot];
        assert!(p.active, "the 0-slot minion lives at cap 1");
        // The idle lerp moved the centre toward (395, 296) — 12 ticks of
        // 5% closing: 500 − 105·(1 − 0.95¹²) ≈ 451.7.
        let cx = p.pos.x + p.w * 0.5;
        assert!(cx < 470.0 && cx > 430.0, "the drift ran: {cx}");
        assert_eq!(p.time_left, 1, "the pin 2 minus the tail decrement");
        assert_eq!(p.frame, 1, "12 ticks: one 9-wrap + 3 counts");
        assert_eq!(p.frame_counter, 3);
        assert!(rng.draws.is_empty(), "the arm draws NO Next: {:?}", rng.draws);
        assert_eq!(rng.floats, 0, "the arm draws NO NextFloat");
    }
}

#[cfg(test)]
mod s1_p_i25_dragon_tests {
    //! S1-P-i25/i56 — the Stardust Dragon chain arm (`AI_121_StardustDragon`,
    //! `Projectile.cs:42824-43080`, the dispatch `:34892-34895`). The i25
    //! branch deferred the chain AI; the gate ported it so the i56 coverage
    //! pin (`UNARMED_ROWED`) stays EMPTY. The witnesses mirror the C# on the
    //! port's seams: the row slice, the owner-inactive kill, the head's
    //! hover/chase steering, the segment's key-linked follow + the parent
    //! writes, the tail-on-head double kill, the orphan relink scan, the
    //! scale-growth truncation, and the ONE-gate-draw RNG census.
    use super::*;
    use crate::npc::{Npc, NpcKind};
    use crate::player::Player;

    fn world() -> World {
        World::new("t".into(), 256, 128)
    }

    /// The owner at a fixed spot: centre (410, 321) — x 400 + WIDTH/2,
    /// y 300 + height/2 (42). The summon flag live (the timeLeft pin).
    fn owner(w: &World) -> Player {
        let mut p = Player::spawn(w);
        p.x = 400.0;
        p.y = 300.0;
        p.stardust_dragon = true;
        p.max_minions = 3;
        p
    }

    /// The scripted stream (the guardian `CensusRng` shape): records every
    /// draw; `next_range` returns max−1 so the dust GATE never fires (the
    /// body is skipped either way — the draw itself is the census).
    struct CensusRng {
        draws: Vec<(i32, i32)>,
        floats: usize,
    }
    impl tr_core::loot::DropRng for CensusRng {
        fn next_range(&mut self, min: i32, max: i32) -> i32 {
            self.draws.push((min, max));
            max - 1
        }
        fn next_float(&mut self) -> f32 {
            self.floats += 1;
            0.5
        }
    }

    /// One full pool tick with the local player driving (the channel
    /// `tick` shape) and the scripted stream.
    fn tick(pool: &mut ProjectilePool, w: &mut World, p: &mut Player, rng: &mut CensusRng) {
        let mut npcs: Vec<Npc> = Vec::new();
        let center = p.center();
        pool.update(
            w,
            &mut npcs,
            Some(center),
            None,
            Some(p),
            YoyoInputs::default(),
            FlailInputs::default(),
            rng,
            0,
            false,
        );
    }

    /// A chaseable NPC by CENTRE — the Zombie's 18x40 box (the guardian
    /// fixture shape).
    fn npc_centered(cx: f32, cy: f32) -> Npc {
        let mut n = Npc::new(NpcKind::Zombie, 0.0, 0.0, 1, 0.0);
        n.max_hp = 40;
        n.hp = 40;
        let (w, h) = n.size();
        n.x = cx - w * 0.5;
        n.y = cy - h * 0.5;
        n
    }

    /// The row slice pins (`Projectile.cs:6729-6753`): the 24x24 box, the
    /// style, the *=5 life, the LOCAL pair (7), alpha 255, and the slot
    /// split — head/tail 0, bodies 0.5 (`:6735-6738`).
    #[test]
    fn s1_p_i25_the_dragon_rows_match_set_defaults() {
        for kind in [
            STARDUST_DRAGON_HEAD,
            STARDUST_DRAGON_BODY_1,
            STARDUST_DRAGON_BODY_2,
            STARDUST_DRAGON_TAIL,
        ] {
            let d = proj_data(kind).unwrap();
            assert_eq!((d.w, d.h), (24.0, 24.0), ":6739-6740");
            assert_eq!(d.ai_style, 121, ":6741");
            assert_eq!(d.penetrate, -1, ":6742");
            assert_eq!(d.time_left, 18000, ":6743 — the *= 5 off 3600 (:787)");
            assert!(d.minion, ":6744");
            assert!(d.ignore_water, ":6746");
            assert!(!d.tile_collide, ":6747");
            assert_eq!(d.alpha, 255, ":6748");
            assert!(d.uses_local_immunity, ":6751");
            assert_eq!(d.local_hit_cooldown, 7, ":6752");
            let slots = match kind {
                STARDUST_DRAGON_BODY_1 | STARDUST_DRAGON_BODY_2 => 0.5,
                _ => 0.0,
            };
            assert_eq!(d.minion_slots, slots, ":6735-6738 — the body half-slots");
        }
    }

    /// The owner-inactive kill (`:42831-42835`): no player → dead slot,
    /// and the kill runs AHEAD of the chain block (no gate draw).
    #[test]
    fn s1_p_i25_the_inactive_owner_kills_the_dragon() {
        let mut w = world();
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_with_data_ai_owned(STARDUST_DRAGON_HEAD, 0, 400.0, 300.0, 0.0, 0.0, 40, 0.0, 0.0, 0.0)
            .unwrap();
        let mut rng = CensusRng { draws: Vec::new(), floats: 0 };
        let mut npcs: Vec<Npc> = Vec::new();
        pool.update(
            &mut w,
            &mut npcs,
            None,
            None,
            None,
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut rng,
            0,
            false,
        );
        assert!(!pool.slots()[slot].active, ":42833");
        assert_eq!(pool.slots()[slot].time_left, 0, "the port's kill() convention");
        assert!(rng.draws.is_empty(), "the kill precedes the gate draw");
    }

    /// The head's hover steering (`:42930-42965`): 300 px right of the
    /// owner, no NPC — the 0.2 ladder rung, the X gate fires (300 > 20),
    /// the Y gate rests (0 ≤ 10), the −0.1 lift, no clamp. The pin drops
    /// timeLeft to 2 (the tail decrements to 1), the fade runs 255 → 213,
    /// the box grows to the chain base 30 keeping the centre, and the ONE
    /// gate draw lands (`:42850`).
    #[test]
    fn s1_p_i25_the_head_hovers_toward_the_owner() {
        let mut w = world();
        let mut p = owner(&w);
        let mut pool = ProjectilePool::new();
        // Centre (710, 321): 300 px right of the owner's (410, 321).
        let slot = pool
            .spawn_with_data_ai_owned(STARDUST_DRAGON_HEAD, 0, 698.0, 309.0, 0.0, 0.0, 40, 0.0, 0.0, 0.0)
            .unwrap();
        let mut rng = CensusRng { draws: Vec::new(), floats: 0 };
        tick(&mut pool, &mut w, &mut p, &mut rng);
        let d = &pool.slots()[slot];
        assert!(d.active);
        assert_eq!(d.vel, Vec2::new(-0.2, -0.1), "the 0.2 X accel toward the owner + the −0.1 lift");
        assert_eq!(d.scale, 1.0, "localAI[0] = 0 → 1 + 0·0.01 (:42976)");
        assert_eq!((d.w, d.h), (30.0, 30.0), "(int)(30·1) — the chain base (:42977)");
        assert_eq!(d.alpha, 213, "255 − 42 (:42987)");
        assert_eq!(d.time_left, 1, "the pin 2 minus the tail decrement (:42847)");
        assert_eq!(d.sprite_direction, -1, "vel.x < 0 (:42969)");
        // The centre kept through the resize, then the free integrate.
        let cx = d.pos.x + d.w * 0.5;
        let cy = d.pos.y + d.h * 0.5;
        assert!((cx - 709.8).abs() < 0.01, "centre 710 − 0.2: {cx}");
        assert!((cy - 320.9).abs() < 0.01, "centre 321 − 0.1: {cy}");
        assert_eq!(rng.draws, vec![(0, 30)], "ONE Next(30) gate (:42850)");
        assert_eq!(rng.floats, 0);
    }

    /// The head's chase steering (`:42901-42928`): an NPC 100 px ahead —
    /// the <300 ladder rung 0.8, the size gate passes, the 0.8·1.5 accel,
    /// the forward dot skips the damp, no clamp. The scan keeps the LAST
    /// eligible NPC (`:42890-42897` — no break).
    #[test]
    fn s1_p_i25_the_head_chases_the_scanned_target() {
        let mut w = world();
        let mut p = owner(&w);
        let mut pool = ProjectilePool::new();
        // Head centre (710, 321); the NPC centre (810, 321) — 100 px ahead,
        // 400 px from the owner (< 1000) and 100 from the head (< 700).
        let slot = pool
            .spawn_with_data_ai_owned(STARDUST_DRAGON_HEAD, 0, 698.0, 309.0, 0.0, 0.0, 40, 0.0, 0.0, 0.0)
            .unwrap();
        let mut npcs = vec![npc_centered(810.0, 321.0)];
        let mut rng = CensusRng { draws: Vec::new(), floats: 0 };
        let center = p.center();
        pool.update(
            &mut w,
            &mut npcs,
            Some(center),
            None,
            Some(&mut p),
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut rng,
            0,
            false,
        );
        let d = &pool.slots()[slot];
        assert_eq!(d.vel, Vec2::new(1.2, 0.0), "0.8·1.5 along +X (:42918)");
        assert!((d.rot - std::f32::consts::FRAC_PI_2).abs() < 1e-5, "atan2(0,1.2)+π/2 (:42967)");
    }

    /// The segment follow (`:43007-43076`): the key-linked body reads its
    /// head parent, writes the parent's scale counter (child+1), keeps the
    /// centre through the resize, stands off 16·scale along the ROTATION-
    /// BLENDED gap, and fades unconditionally. The head keeps its backlink
    /// (the 625 exemption, `:43018-43021`).
    #[test]
    fn s1_p_i25_the_body_follows_its_key_linked_head() {
        let w = world();
        let mut p = owner(&w);
        let mut pool = ProjectilePool::new();
        // Head centre (412, 312), rotation 0.5; body centre (512, 312).
        let head = pool
            .spawn_with_data_ai_owned(STARDUST_DRAGON_HEAD, 0, 400.0, 300.0, 0.0, 0.0, 40, 0.0, 0.0, 0.0)
            .unwrap();
        pool.slots_mut()[head].rot = 0.5;
        let key = pool.key_of(head);
        let body = pool
            .spawn_with_data_ai_owned(
                STARDUST_DRAGON_BODY_1, 0, 500.0, 300.0, 0.0, 0.0, 40, 0.0,
                f32::from_bits(key as u32), 0.0,
            )
            .unwrap();
        let mut rng = CensusRng { draws: Vec::new(), floats: 0 };
        pool.dragon_step(body, &w, &[], Some(&mut p), &mut rng, 0);
        // The parent writes: the counter is the CHILD's + 1; the head's
        // backlink stays untouched (the 625 exemption).
        assert_eq!(pool.slots()[head].local_ai[0], 1.0, ":43017");
        assert_eq!(pool.slots()[head].local_ai[1], 0.0, ":43018-43021 — no head backlink");
        let d = &pool.slots()[body];
        assert_eq!(d.alpha, 213, "the UNCONDITIONAL −42 (:43056)");
        assert_eq!(d.vel, Vec2::ZERO, ":43061");
        assert_eq!(d.scale, 1.0, "the parent's clamped scale (:43014/:43069)");
        assert_eq!((d.w, d.h), (30.0, 30.0), "(int)(30·1) (:43070)");
        // The gap (−100, 0) rotated by wrap(0.5−0)·0.1 = 0.05:
        // (−99.875, −4.9979); the stand-off is 16·1 along its heading.
        let cx = d.pos.x + d.w * 0.5;
        let cy = d.pos.y + d.h * 0.5;
        assert!((cx - 427.98).abs() < 0.02, "412 + 16·cos(0.05): {cx}");
        assert!((cy - 312.80).abs() < 0.02, "312 + 16·sin(0.05): {cy}");
        assert_eq!(d.sprite_direction, -1, "the gap points −X (:43076)");
        assert_eq!(rng.draws, vec![(0, 30)], "ONE gate draw per chain slot");
    }

    /// The tail-on-head contact (`:43022-43027`): the local owner's 628
    /// resolving a 625 parent kills BOTH and returns (the parent writes
    /// still ran — the counter precedes the kill).
    #[test]
    fn s1_p_i25_the_tail_on_head_contact_kills_both() {
        let w = world();
        let mut p = owner(&w);
        let mut pool = ProjectilePool::new();
        let head = pool
            .spawn_with_data_ai_owned(STARDUST_DRAGON_HEAD, 0, 400.0, 300.0, 0.0, 0.0, 40, 0.0, 0.0, 0.0)
            .unwrap();
        let key = pool.key_of(head);
        let tail = pool
            .spawn_with_data_ai_owned(
                STARDUST_DRAGON_TAIL, 0, 500.0, 300.0, 0.0, 0.0, 40, 0.0,
                f32::from_bits(key as u32), 0.0,
            )
            .unwrap();
        let mut rng = CensusRng { draws: Vec::new(), floats: 0 };
        pool.dragon_step(tail, &w, &[], Some(&mut p), &mut rng, 0);
        assert!(!pool.slots()[head].active, ":43024 — proj.Kill()");
        assert!(!pool.slots()[tail].active, ":43025 — this.Kill()");
        assert_eq!(pool.slots()[head].local_ai[0], 1.0, "the write precedes the kill");
    }

    /// The orphan relink (`:43029-43045`): a stale key (slot 5, never
    /// spawned) fails the lookup; the scan finds the head whose backlink
    /// names the key's INDEX (5), re-keys onto it and stamps the backlink
    /// with the segment's slot. The early return skips the fade + clamp.
    #[test]
    fn s1_p_i25_the_orphan_segment_relinks_through_the_backlink_scan() {
        let w = world();
        let mut p = owner(&w);
        let mut pool = ProjectilePool::new();
        let head = pool
            .spawn_with_data_ai_owned(STARDUST_DRAGON_HEAD, 0, 400.0, 300.0, 0.0, 0.0, 40, 0.0, 0.0, 0.0)
            .unwrap();
        pool.slots_mut()[head].local_ai[1] = 5.0;
        // The stale key names slot 5 (generation 0 — never spawned).
        let stale = crate::net::projectile_key(0, 5, 0);
        let body = pool
            .spawn_with_data_ai_owned(
                STARDUST_DRAGON_BODY_1, 0, 500.0, 300.0, 0.0, 0.0, 40, 0.0,
                f32::from_bits(stale as u32), 0.0,
            )
            .unwrap();
        let mut rng = CensusRng { draws: Vec::new(), floats: 0 };
        pool.dragon_step(body, &w, &[], Some(&mut p), &mut rng, 0);
        let new_key = pool.key_of(head);
        assert_eq!(
            pool.slots()[body].ai[0].to_bits(),
            new_key as u32,
            ":43040 — re-keyed onto the head"
        );
        assert_eq!(pool.slots()[head].local_ai[1], body as f32, ":43041 — the backlink");
        assert!(pool.slots()[body].net_update, ":43042");
        assert_eq!(pool.slots()[body].alpha, 255, "the return skips the fade");
        assert_eq!(pool.slots()[body].pos, Vec2::new(500.0, 300.0), "the return skips the clamp");
    }

    /// The scale growth (`:42974-42978`): the counter (written by the
    /// segments) clamps 0..50 and feeds 1 + n·0.01; the box truncates —
    /// counter 10 → scale 1.1 → (int)(30·1.1) = 33, centre kept.
    #[test]
    fn s1_p_i25_the_head_scale_grows_with_the_chain_counter() {
        let w = world();
        let mut p = owner(&w);
        let mut pool = ProjectilePool::new();
        let head = pool
            .spawn_with_data_ai_owned(STARDUST_DRAGON_HEAD, 0, 400.0, 300.0, 0.0, 0.0, 40, 0.0, 0.0, 0.0)
            .unwrap();
        pool.slots_mut()[head].local_ai[0] = 10.0;
        let mut rng = CensusRng { draws: Vec::new(), floats: 0 };
        pool.dragon_step(head, &w, &[], Some(&mut p), &mut rng, 0);
        let d = &pool.slots()[head];
        assert_eq!(d.scale, 1.1, "1 + 10·0.01 (:42976)");
        assert_eq!((d.w, d.h), (33.0, 33.0), "(int)(30·1.1) = 33 (:42977)");
        let cx = d.pos.x + d.w * 0.5;
        let cy = d.pos.y + d.h * 0.5;
        assert!((cx - 412.0).abs() < 0.01, "the centre kept: {cx}");
        assert!((cy - 312.0).abs() < 0.01, "the centre kept: {cy}");
    }
}
